export const BODY = {"level-9":{"id":"level-9","kind":"level","level":9,"src":"level:9","title":"Level 9 · The Lighthouse","body":"Roots that never end, decimals that recur, loans and compound interest, sequences, straight-line graphs and inequalities, trigonometry and bearings, scatter graphs and tree diagrams.","route":"#/atlas","cta":"See the road"},"land-l9-powers":{"id":"land-l9-powers","kind":"land","level":9,"src":"land:l9-powers","title":"Roots that never end — in The Square Palace","body":"6 stops on this stretch of the road: How a square ends · Squaring just below a ten · Either side of a square · Squares near a hundred · Which square roots are fractions · The next square up.","art":"art/w-palace.webp","route":"#/world/palace","cta":"Visit Palace"},"land-l9-decimals":{"id":"land-l9-decimals","kind":"land","level":9,"src":"land:l9-decimals","title":"Decimals that never end — in The Decimal Dock","body":"3 stops on this stretch of the road: Ratio: simplify and share · Decimals that end · Percentages swap.","art":"art/w-dock.webp","route":"#/world/dock","cta":"Visit Dock"},"land-l9-money":{"id":"land-l9-money","kind":"land","level":9,"src":"land:l9-money","title":"Bills, loans and interest — in Coin Street","body":"4 stops on this stretch of the road: Simple interest · Interest on interest · Splitting a bill fairly · What borrowing costs.","art":"art/w-coinstreet.webp","route":"#/world/coinstreet","cta":"Visit Coins"},"land-l9-algebra":{"id":"land-l9-algebra","kind":"land","level":9,"src":"land:l9-algebra","title":"Sequences and inequalities — in Set Island","body":"4 stops on this stretch of the road: Collecting like terms · The nth term · Straight-line graphs · Inequalities.","art":"art/w-setisland.webp","route":"#/world/setisland","cta":"Visit Set Island"},"land-l9-shape":{"id":"land-l9-shape","kind":"land","level":9,"src":"land:l9-shape","title":"Trigonometry and bearings — in The Lighthouse","body":"5 stops on this stretch of the road: Naming the sides · Tan: how tall is the tower? · Sin and cos: the ladder · The three special angles · Bearings: the way back.","art":"art/w-lighthouse.webp","route":"#/world/lighthouse","cta":"Visit Lighthouse"},"land-l9-data":{"id":"land-l9-data","kind":"land","level":9,"src":"land:l9-data","title":"Scatter graphs and trees — in The Data Carnival","body":"4 stops on this stretch of the road: Scatter graphs and correlation · The line of best fit · Tree diagrams · Expected frequency.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"hook-interest-simple-hook":{"id":"hook-interest-simple-hook","kind":"hook","src":"stop:interest-simple#hook","title":"Can you? — Simple interest","body":"The bank in this story pays 5% a year. Put 200 coins in for 3 years, taking the interest out each year. How much interest altogether?","cta":"Find out how","level":9,"route":"#/stop/interest-simple"},"idea-interest-simple-case1":{"id":"idea-interest-simple-case1","kind":"idea","src":"stop:interest-simple#case1","title":"Simple interest: What is in the account","body":"The question asks for the account, not just the interest — so add the interest to the coins put in.","cta":"See it worked","level":9,"route":"#/stop/interest-simple"},"why-interest-simple-why2":{"id":"why-interest-simple-why2","kind":"why","src":"stop:interest-simple#why2","title":"Why “Simple interest” works","body":"The rate here is the story's own number. Real rates are different in every place and change over time — the maths is the same whatever the rate is.","cta":"See why","level":9,"route":"#/stop/interest-simple"},"moment-interest-simple-beat4":{"id":"moment-interest-simple-beat4","kind":"moment","src":"story:interest-simple#beat4","badge":{"id":"story","label":"A story"},"title":"The story bank — on the notepad","body":"Ines: Three years of it. 10 × 3 = 30","cta":"Read the story","level":9,"route":"#/stop/interest-simple"},"trick-interest-compound-idea":{"id":"trick-interest-compound-idea","kind":"trick","src":"stop:interest-compound#idea","title":"Interest on interest","body":"Each year, add the interest to the account — so next year the interest is worked out on the bigger amount. With compound interest the interest is not taken out; it joins the account. Year 1: 5% of 200 is 10, so there are 210 coins. Year 2: 5% of 210 is 10.50, so there are 220.50 — not 220.","cta":"Learn the trick","level":9,"route":"#/stop/interest-compound"},"story-interest-compound-open":{"id":"story-interest-compound-open","kind":"story","src":"story:interest-compound#open","badge":{"id":"story","label":"A story"},"title":"Leave it in","body":"Kwame puts 200 coins in the story's bank at 5% a year, and leaves the interest in. — with Ines and Kwame.","art":"art/s-city.webp","cta":"Read the story","level":9,"route":"#/stop/interest-compound"},"idea-interest-compound-case0":{"id":"idea-interest-compound-case0","kind":"idea","src":"stop:interest-compound#case0","title":"Interest on interest: The account, year by year","body":"Each year's interest is worked out on the bigger amount, so go one year at a time — never multiply one year's interest by the years.","cta":"See it worked","level":9,"route":"#/stop/interest-compound"},"idea-interest-compound-case1":{"id":"idea-interest-compound-case1","kind":"idea","src":"stop:interest-compound#case1","title":"Interest on interest: Compound beats simple by…","body":"Work out both accounts after two years and take one from the other. The gap is the interest earned on interest.","cta":"See it worked","level":9,"route":"#/stop/interest-compound"},"why-interest-compound-why1":{"id":"why-interest-compound-why1","kind":"why","src":"stop:interest-compound#why1","title":"Why “Interest on interest” works","body":"That extra half-coin is interest on the 10 coins of interest: 5% of 10 is 0.50. Every year the interest itself starts earning, so the gap from simple interest grows each year. After two years the gap is exactly r% of r% of the amount put in.","cta":"See why","level":9,"route":"#/stop/interest-compound"},"algebra-interest-compound-alg":{"id":"algebra-interest-compound-alg","kind":"algebra","src":"stop:interest-compound#alg","title":"The algebra behind “Interest on interest”","body":"A = P × (1 + r/100)ⁿ;  after 2 years, compound − simple = P × (r/100)²","cta":"See why","level":9,"route":"#/stop/interest-compound"},"moral-interest-compound-beat5":{"id":"moral-interest-compound-beat5","kind":"moral","src":"story:interest-compound#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Leave it in”","body":"220.50 coins. The gap grows every year it stays in.","cta":"Read the story","level":9,"route":"#/stop/interest-compound"},"try-interest-compound-L9":{"id":"try-interest-compound-L9","kind":"try","level":9,"src":"try:interest-compound@9/1#0","title":"Interest on interest — your turn","route":"#/stop/interest-compound","cta":"Practise this stop","play":{"q":"The story's bank pays 9% a year and each year's interest stays in the account (compound). Rafi puts in 2800 coins. How many coins after 2 years?","opts":["3326.68","3052","3326.69"],"after":"Each year, add the interest to the account — so next year the interest is worked out on the bigger amount."}},"trick-bill-split-idea":{"id":"trick-bill-split-idea","kind":"trick","src":"stop:bill-split#idea","title":"Splitting a bill fairly","body":"Add the bill, add the percentage on the whole bill, then divide by the number of people. The percentage is charged on the whole bill, so add the items first: 24 + 18 + 30 = 72. Adding 10% means paying 110% of it: 72 × 1.1 = 79.20.","cta":"Learn the trick","level":9,"route":"#/stop/bill-split"},"story-bill-split-open":{"id":"story-bill-split-open","kind":"story","src":"story:bill-split#open","badge":{"id":"story","label":"A story"},"title":"Three at the café","body":"Mira, Theo and a friend eat at a café. Their bill is 24 + 18 + 30 coins, and the café adds 10%. — with Mira and Theo.","art":"art/s-kitchen.webp","cta":"Read the story","level":9,"route":"#/stop/bill-split"},"hook-bill-split-hook":{"id":"hook-bill-split-hook","kind":"hook","src":"stop:bill-split#hook","title":"Can you? — Splitting a bill fairly","body":"3 friends have a café bill of 24 + 18 + 30 coins, and the café adds 10%. They split it equally. How much does each pay?","cta":"Find out how","level":9,"route":"#/stop/bill-split"},"worked-bill-split-worked0":{"id":"worked-bill-split-worked0","kind":"worked","src":"stop:bill-split#worked0","title":"Worked out — Splitting a bill fairly","body":"3 friends have a café bill of 24 + 18 + 30 coins, and the café adds 10%. They split it equally. How much does each pay?: The bill: 24 + 18 + 30 → 72 · With 10% added: 72 × 1.1 → 79.2 · Each of 3: ÷ 3 → 26.4","cta":"Watch it step by step","level":9,"route":"#/stop/bill-split"},"why-bill-split-why1":{"id":"why-bill-split-why1","kind":"why","src":"stop:bill-split#why1","title":"Why “Splitting a bill fairly” works","body":"Split equally, each of the 3 pays 79.20 ÷ 3 = 26.40. You could also add 10% to each person's own share of 24 coins — 26.40 again — because taking a percentage and sharing equally can be done in either order.","cta":"See why","level":9,"route":"#/stop/bill-split"},"why-bill-split-why2":{"id":"why-bill-split-why2","kind":"why","src":"stop:bill-split#why2","title":"Why “Splitting a bill fairly” works","body":"\"Equal\" is one kind of fair. Another is each paying for what they had, plus 10% of it. The maths works for both; the friends choose which is fair to them.","cta":"See why","level":9,"route":"#/stop/bill-split"},"algebra-bill-split-alg":{"id":"algebra-bill-split-alg","kind":"algebra","src":"stop:bill-split#alg","title":"The algebra behind “Splitting a bill fairly”","body":"each = (sum of items) × (100 + p) ÷ 100 ÷ people","cta":"See why","level":9,"route":"#/stop/bill-split"},"moment-bill-split-beat2":{"id":"moment-bill-split-beat2","kind":"moment","src":"story:bill-split#beat2","badge":{"id":"story","label":"A story"},"title":"Three at the café — on the notepad","body":"Theo: Split three ways. 79.2 ÷ 3 = 26.4","cta":"Read the story","level":9,"route":"#/stop/bill-split"},"moral-bill-split-beat5":{"id":"moral-bill-split-beat5","kind":"moral","src":"story:bill-split#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Three at the café”","body":"26.40 each. Either order works.","cta":"Read the story","level":9,"route":"#/stop/bill-split"},"try-bill-split-L9":{"id":"try-bill-split-L9","kind":"try","level":9,"src":"try:bill-split@9/1#0","title":"Splitting a bill fairly — your turn","route":"#/stop/bill-split","cta":"Practise this stop","play":{"q":"2 friends have a café bill of 7 + 15 coins, and the café adds 10%. They split it equally. How much does each pay?","opts":["12.1","22","24.2"],"after":"Add the bill, add the percentage on the whole bill, then divide by the number of people."}},"trick-cost-of-borrowing-idea":{"id":"trick-cost-of-borrowing-idea","kind":"trick","src":"stop:cost-of-borrowing#idea","title":"What borrowing costs","body":"Add up every payment, then take away what was borrowed. The extra is the price of borrowing. A loan lets you have something now and pay for it over time. That is useful, and like anything useful it has a price: you pay back more than you borrowed. 5 payments of 22 is 110 coins, for a loan of 100 — so the loan cost 10 coins.","cta":"Learn the trick","level":9,"route":"#/stop/cost-of-borrowing"},"story-cost-of-borrowing-open":{"id":"story-cost-of-borrowing-open","kind":"story","src":"story:cost-of-borrowing#open","badge":{"id":"story","label":"A story"},"title":"Five payments","body":"In the bike shop, Kwame can borrow 100 coins for a bike and pay back 5 payments of 22 coins. — with Kwame and Ines.","art":"art/s-shop.webp","cta":"Read the story","level":9,"route":"#/stop/cost-of-borrowing"},"hook-cost-of-borrowing-hook":{"id":"hook-cost-of-borrowing-hook","kind":"hook","src":"stop:cost-of-borrowing#hook","title":"Can you? — What borrowing costs","body":"Kwame borrows 100 coins and pays it back as 5 payments of 22 coins. How much extra did the loan cost?","cta":"Find out how","level":9,"route":"#/stop/cost-of-borrowing"},"idea-cost-of-borrowing-case0":{"id":"idea-cost-of-borrowing-case0","kind":"idea","src":"stop:cost-of-borrowing#case0","title":"What borrowing costs: The extra, in coins","body":"Multiply out the payments to see what was paid back altogether, then take away what was borrowed.","cta":"See it worked","level":9,"route":"#/stop/cost-of-borrowing"},"idea-cost-of-borrowing-case1":{"id":"idea-cost-of-borrowing-case1","kind":"idea","src":"stop:cost-of-borrowing#case1","title":"What borrowing costs: The extra, as a percentage","body":"To compare loans of different sizes, divide the extra by the loan and multiply by 100.","cta":"See it worked","level":9,"route":"#/stop/cost-of-borrowing"},"worked-cost-of-borrowing-worked1":{"id":"worked-cost-of-borrowing-worked1","kind":"worked","src":"stop:cost-of-borrowing#worked1","title":"Worked out — What borrowing costs: The extra, as a percentage","body":"Vesper borrows 200 coins and pays it back as 4 payments of 55 coins. The extra paid is what percentage of the loan?: Paid back: 4 × 55 → 220 · Extra: 220 − 200 → 20 · As a percentage: 20 ÷ 200 × 100 → 10","cta":"Watch it step by step","level":9,"route":"#/stop/cost-of-borrowing"},"why-cost-of-borrowing-why1":{"id":"why-cost-of-borrowing-why1","kind":"why","src":"stop:cost-of-borrowing#why1","title":"Why “What borrowing costs” works","body":"Small payments can hide a big price, because nobody adds them up at the shop. Always multiply out: payments × how many, then compare with what you borrowed.","cta":"See why","level":9,"route":"#/stop/cost-of-borrowing"},"why-cost-of-borrowing-why2":{"id":"why-cost-of-borrowing-why2","kind":"why","src":"stop:cost-of-borrowing#why2","title":"Why “What borrowing costs” works","body":"To compare two loans of different sizes, turn the extra into a percentage of the loan: 10 extra on 100 borrowed is 10%. Borrowing is not good or bad — it is a tool, and this is how you read its price tag.","cta":"See why","level":9,"route":"#/stop/cost-of-borrowing"},"algebra-cost-of-borrowing-alg":{"id":"algebra-cost-of-borrowing-alg","kind":"algebra","src":"stop:cost-of-borrowing#alg","title":"The algebra behind “What borrowing costs”","body":"cost of the loan = payments × number of payments − amount borrowed","cta":"See why","level":9,"route":"#/stop/cost-of-borrowing"},"moment-cost-of-borrowing-beat3":{"id":"moment-cost-of-borrowing-beat3","kind":"moment","src":"story:cost-of-borrowing#beat3","badge":{"id":"story","label":"A story"},"title":"Five payments — on the notepad","body":"Kwame: For a loan of 100. So the extra is… 110 − 100 = 10","cta":"Read the story","level":9,"route":"#/stop/cost-of-borrowing"},"moral-cost-of-borrowing-beat5":{"id":"moral-cost-of-borrowing-beat5","kind":"moral","src":"story:cost-of-borrowing#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Five payments”","body":"10 coins to have the bike now. Now I can decide if it is worth it.","cta":"Read the story","level":9,"route":"#/stop/cost-of-borrowing"},"try-cost-of-borrowing-L9":{"id":"try-cost-of-borrowing-L9","kind":"try","level":9,"src":"try:cost-of-borrowing@9/1#0","title":"What borrowing costs — your turn","route":"#/stop/cost-of-borrowing","cta":"Practise this stop","play":{"q":"Dax borrows 60 coins and pays it back as 4 payments of 16 coins. How much extra did the loan cost?","opts":["4","64","5"],"after":"Add up every payment, then take away what was borrowed. The extra is the price of borrowing."}},"trick-ending-decimals-idea":{"id":"trick-ending-decimals-idea","kind":"trick","src":"stop:ending-decimals#idea","title":"Decimals that end","body":"Simplify the fraction, then look at the bottom's prime stones. Only 2s and 5s: the decimal ends. Any other stone: it goes on for ever. A decimal that ends is a number of tenths, hundredths or thousandths: 0.175 is 175/1000. And 10, 100, 1000 are built from only two stones — 10 = 2 × 5, 100 = 2 × 2 × 5 × 5. So a fraction can end only if its bottom fits into some 10 × 10 × … — which means its bottom must be made of 2s and 5s only.","cta":"Learn the trick","level":9,"route":"#/stop/ending-decimals"},"story-ending-decimals-open":{"id":"story-ending-decimals-open","kind":"story","src":"story:ending-decimals#open","badge":{"id":"story","label":"A story"},"title":"The calculator screen","body":"At the shop, Theo divides on a calculator. 7 ÷ 40 stops neatly, but 1 ÷ 3 fills the screen with 3s. — with Ines and Theo.","art":"art/s-shop.webp","cta":"Read the story","level":9,"route":"#/stop/ending-decimals"},"hook-ending-decimals-hook":{"id":"hook-ending-decimals-hook","kind":"hook","src":"stop:ending-decimals#hook","title":"Can you? — Decimals that end","body":"7/40 and 1/3 — one ends as a decimal, one goes on for ever. Can you tell which before dividing?","cta":"Find out how","level":9,"route":"#/stop/ending-decimals"},"idea-ending-decimals-case0":{"id":"idea-ending-decimals-case0","kind":"idea","src":"stop:ending-decimals#case0","title":"Decimals that end: It ends","body":"The bottom is made of only 2s and 5s, so it fits into a power of ten: 7/40 = 175/1000 = 0.175.","cta":"See it worked","level":9,"route":"#/stop/ending-decimals"},"worked-ending-decimals-worked0":{"id":"worked-ending-decimals-worked0","kind":"worked","src":"stop:ending-decimals#worked0","title":"Worked out — Decimals that end: It ends","body":"7/40 as a decimal — does it end, or go on for ever?: Simplify 7/40. What is the bottom now? → 40 · Take every 2 and every 5 out of 40. What is left? → 1 · Left with 1: it ends. Anything else: it goes on for ever. So → it ends","cta":"Watch it step by step","level":9,"route":"#/stop/ending-decimals"},"idea-ending-decimals-case1":{"id":"idea-ending-decimals-case1","kind":"idea","src":"stop:ending-decimals#case1","title":"Decimals that end: It goes on for ever","body":"A 3 in the bottom that will not cancel: no ten, hundred or thousand splits into threes, so the digits never stop.","cta":"See it worked","level":9,"route":"#/stop/ending-decimals"},"idea-ending-decimals-case2":{"id":"idea-ending-decimals-case2","kind":"idea","src":"stop:ending-decimals#case2","title":"Decimals that end: A stone that cancels","body":"The trap: 3/12 has a 3 in its bottom, but simplify first — it is 1/4, which is only 2s. So it ends.","cta":"See it worked","level":9,"route":"#/stop/ending-decimals"},"why-ending-decimals-why1":{"id":"why-ending-decimals-why1","kind":"why","src":"stop:ending-decimals#why1","title":"Why “Decimals that end” works","body":"40 = 2 × 2 × 2 × 5. Give it two more 5s and it becomes 1000, so 7/40 = 175/1000 = 0.175 — it ends. But 3 is a stone that no power of ten contains, so no number of tenths or hundredths is ever exactly 1/3. Divide it out and the 3s go on for ever.","cta":"See why","level":9,"route":"#/stop/ending-decimals"},"why-ending-decimals-why2":{"id":"why-ending-decimals-why2","kind":"why","src":"stop:ending-decimals#why2","title":"Why “Decimals that end” works","body":"Simplify first, or you will be fooled. 3/12 has a 3 in its bottom, but 3/12 = 1/4, and 4 = 2 × 2 — so it ends, as 0.25. A stone that cancels away was never really there.","cta":"See why","level":9,"route":"#/stop/ending-decimals"},"algebra-ending-decimals-alg":{"id":"algebra-ending-decimals-alg","kind":"algebra","src":"stop:ending-decimals#alg","title":"The algebra behind “Decimals that end”","body":"a/b in lowest terms ends ⇔ b = 2^m × 5^n","cta":"See why","level":9,"route":"#/stop/ending-decimals"},"moment-ending-decimals-beat2":{"id":"moment-ending-decimals-beat2","kind":"moment","src":"story:ending-decimals#beat2","badge":{"id":"story","label":"A story"},"title":"The calculator screen — on the notepad","body":"Ines: Look at the stones on the bottom. 40 is 2 × 2 × 2 × 5 — only 2s and 5s. 2 × 2 × 2 × 5 = 40","cta":"Read the story","level":9,"route":"#/stop/ending-decimals"},"moral-ending-decimals-beat5":{"id":"moral-ending-decimals-beat5","kind":"moral","src":"story:ending-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The calculator screen”","body":"That’s why 1/3 never ends. And 7/40 is 175 thousandths.","cta":"Read the story","level":9,"route":"#/stop/ending-decimals"},"try-ending-decimals-L9":{"id":"try-ending-decimals-L9","kind":"try","level":9,"src":"try:ending-decimals@9/1#0","title":"Decimals that end — your turn","route":"#/stop/ending-decimals","cta":"Practise this stop","play":{"q":"4/11 as a decimal — does it end, or go on for ever?","opts":["goes on for ever","it ends"],"after":"Simplify the fraction, then look at the bottom's prime stones. Only 2s and 5s: the decimal ends. Any other stone: it goes on for ever."}},"trick-rational-roots-idea":{"id":"trick-rational-roots-idea","kind":"trick","src":"stop:rational-roots#idea","title":"Which square roots are fractions","body":"Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it. A rational number is one that can be written as one integer over another, like 7/1 or 99/14. Squaring a fraction squares its top and its bottom, and squaring doubles every stone: 6 = 2 × 3, so 6 × 6 has two 2s and two 3s. So a square number always has its stones in PAIRS. 50 = 2 × 5 × 5: the 5s pair up, but the 2 is alone. 50 is not a square.","cta":"Learn the trick","level":9,"route":"#/stop/rational-roots"},"story-rational-roots-open":{"id":"story-rational-roots-open","kind":"story","src":"story:rational-roots#open","badge":{"id":"story","label":"A story"},"title":"The lonely stone","body":"Under the stars, Kwame asks Vesper: 7 × 7 is 49. Can √50 be written as one whole number over another? — with Kwame and Vesper.","art":"art/s-night.webp","cta":"Read the story","level":9,"route":"#/stop/rational-roots"},"idea-rational-roots-case0":{"id":"idea-rational-roots-case0","kind":"idea","src":"stop:rational-roots#case0","title":"Which square roots are fractions: A lonely stone","body":"50 = 2 × 5 × 5. The 5s pair up but the 2 is alone, so no fraction squared can ever make 50: √50 is irrational.","cta":"See it worked","level":9,"route":"#/stop/rational-roots"},"idea-rational-roots-case1":{"id":"idea-rational-roots-case1","kind":"idea","src":"stop:rational-roots#case1","title":"Which square roots are fractions: Every stone paired","body":"36 = 2 × 2 × 3 × 3: every stone has a partner, so 36 is a square and √36 = 6 — rational.","cta":"See it worked","level":9,"route":"#/stop/rational-roots"},"idea-rational-roots-case2":{"id":"idea-rational-roots-case2","kind":"idea","src":"stop:rational-roots#case2","title":"Which square roots are fractions: A fraction, all paired","body":"For a fraction in lowest terms, check the top AND the bottom. 4 and 9 are both squares, so √(4/9) = 2/3 — rational.","cta":"See it worked","level":9,"route":"#/stop/rational-roots"},"idea-rational-roots-case3":{"id":"idea-rational-roots-case3","kind":"idea","src":"stop:rational-roots#case3","title":"Which square roots are fractions: A fraction, one lonely","body":"The bottom 9 is a square, but the top 8 = 2 × 2 × 2 leaves a 2 alone. One lonely stone anywhere makes it irrational.","cta":"See it worked","level":9,"route":"#/stop/rational-roots"},"why-rational-roots-why1":{"id":"why-rational-roots-why1","kind":"why","src":"stop:rational-roots#why1","title":"Why “Which square roots are fractions” works","body":"Now suppose √50 were a fraction, a/b. Then 50 × b × b = a × a. The right side has every stone in pairs. On the left, b × b has every stone in pairs too — so the lonely 2 from 50 is still lonely. One number, two different sets of stones: impossible, because every number has exactly one set. So √50 is not any fraction at all.","cta":"See why","level":9,"route":"#/stop/rational-roots"},"algebra-rational-roots-alg":{"id":"algebra-rational-roots-alg","kind":"algebra","src":"stop:rational-roots#alg","title":"The algebra behind “Which square roots are fractions”","body":"√n is rational ⇔ n is a perfect square ⇔ every prime stone of n appears an even number of times","cta":"See why","level":9,"route":"#/stop/rational-roots"},"moral-rational-roots-beat6":{"id":"moral-rational-roots-beat6","kind":"moral","src":"story:rational-roots#beat6","badge":{"id":"story","label":"A story"},"title":"Vesper, in “The lonely stone”","body":"So √50 is irrational. A real length — but no fraction is exactly it.","cta":"Read the story","level":9,"route":"#/stop/rational-roots"},"try-rational-roots-L9":{"id":"try-rational-roots-L9","kind":"try","level":9,"src":"try:rational-roots@9/1#0","title":"Which square roots are fractions — your turn","route":"#/stop/rational-roots","cta":"Practise this stop","play":{"q":"√25 — rational or irrational?","opts":["rational","irrational"],"after":"Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it."}},"trick-square-near-100-idea":{"id":"trick-square-near-100-idea","kind":"trick","src":"stop:square-near-100#idea","title":"Squares near a hundred","body":"Take the number down by its own gap from 100; then square the gap for the last two digits. 96 is 4 short of 100. Go down another 4: 92. Square the gap: 16. Answer: 9216.","cta":"Learn the trick","level":9,"route":"#/stop/square-near-100"},"story-square-near-100-open":{"id":"story-square-near-100-open","kind":"story","src":"story:square-near-100#open","badge":{"id":"story","label":"A story"},"title":"Meeting in the middle","body":"Mira knows squares. Kwame knows the numbers near a hundred. Today’s question belongs to both of them: 96². — with Mira and Kwame.","art":"art/s-night.webp","cta":"Read the story","level":9,"route":"#/stop/square-near-100"},"hook-square-near-100-hook":{"id":"hook-square-near-100-hook","kind":"hook","src":"stop:square-near-100#hook","title":"Can you? — Squares near a hundred","body":"96² — without multiplying 96 by 96.","cta":"Find out how","level":9,"route":"#/stop/square-near-100"},"idea-square-near-100-case0":{"id":"idea-square-near-100-case0","kind":"idea","src":"stop:square-near-100#case0","title":"Squares near a hundred: Short of 100","body":"Below 100, go DOWN by the gap a second time, then write the gap squared on the end.","cta":"See it worked","level":9,"route":"#/stop/square-near-100"},"worked-square-near-100-worked0":{"id":"worked-square-near-100-worked0","kind":"worked","src":"stop:square-near-100#worked0","title":"Worked out — Squares near a hundred: Short of 100","body":"96²: How far from 100? (short) → 4 · Go down again: 96 − 4 → 92 · Square the gap: 4² → 16 · 92 hundreds and 16 → 9216","cta":"Watch it step by step","level":9,"route":"#/stop/square-near-100"},"idea-square-near-100-case1":{"id":"idea-square-near-100-case1","kind":"idea","src":"stop:square-near-100#case1","title":"Squares near a hundred: Over 100","body":"Above 100, go UP by the gap a second time instead. The squared gap goes on the end just the same.","cta":"See it worked","level":9,"route":"#/stop/square-near-100"},"worked-square-near-100-worked1":{"id":"worked-square-near-100-worked1","kind":"worked","src":"stop:square-near-100#worked1","title":"Worked out — Squares near a hundred: Over 100","body":"104²: How far from 100? (over) → 4 · Go up again: 104 + 4 → 108 · Square the gap: 4² → 16 · 108 hundreds and 16 → 10816","cta":"Watch it step by step","level":9,"route":"#/stop/square-near-100"},"idea-square-near-100-case2":{"id":"idea-square-near-100-case2","kind":"idea","src":"stop:square-near-100#case2","title":"Squares near a hundred: A tiny gap","body":"The squared gap is a single digit, but it still takes two places: 2² is written 04.","cta":"See it worked","level":9,"route":"#/stop/square-near-100"},"worked-square-near-100-worked2":{"id":"worked-square-near-100-worked2","kind":"worked","src":"stop:square-near-100#worked2","title":"Worked out — Squares near a hundred: A tiny gap","body":"98²: How far from 100? (short) → 2 · Go down again: 98 − 2 → 96 · Square the gap: 2² → 4 · 96 hundreds and 4 → 9604","cta":"Watch it step by step","level":9,"route":"#/stop/square-near-100"},"idea-square-near-100-case3":{"id":"idea-square-near-100-case3","kind":"idea","src":"stop:square-near-100#case3","title":"Squares near a hundred: A big gap","body":"The squared gap is 100 or more — too big for two places — so its hundred carries across to join the rest.","cta":"See it worked","level":9,"route":"#/stop/square-near-100"},"worked-square-near-100-worked3":{"id":"worked-square-near-100-worked3","kind":"worked","src":"stop:square-near-100#worked3","title":"Worked out — Squares near a hundred: A big gap","body":"88²: How far from 100? (short) → 12 · Go down again: 88 − 12 → 76 · Square the gap: 12² → 144 · 76 hundreds and 144 → 7744","cta":"Watch it step by step","level":9,"route":"#/stop/square-near-100"},"why-square-near-100-why1":{"id":"why-square-near-100-why1","kind":"why","src":"stop:square-near-100#why1","title":"Why “Squares near a hundred” works","body":"Above works the same way, going up: 103 is 3 over, 103 + 3 = 106, 3² = 09, so 10609. It is the Near-a-hundred cross with both numbers the same.","cta":"See why","level":9,"route":"#/stop/square-near-100"},"why-square-near-100-why2":{"id":"why-square-near-100-why2","kind":"why","src":"stop:square-near-100#why2","title":"Why “Squares near a hundred” works","body":"The squared gap always gets two places. If it is under 10, write a 0 in front (09). If it is 100 or more, the hundred carries: 88 is 12 short, 88 − 12 = 76, 12² = 144, so 7600 + 144 = 7744.","cta":"See why","level":9,"route":"#/stop/square-near-100"},"algebra-square-near-100-alg":{"id":"algebra-square-near-100-alg","kind":"algebra","src":"stop:square-near-100#alg","title":"The algebra behind “Squares near a hundred”","body":"(100 − d)² = 100(100 − 2d) + d²","cta":"See why","level":9,"route":"#/stop/square-near-100"},"sutra-square-near-100-sutra":{"id":"sutra-square-near-100-sutra","kind":"sutra","src":"stop:square-near-100#sutra","title":"Yāvadūnam","body":"“by however much it falls short” — the sutra behind Squares near a hundred.","cta":"Open the stop","level":9,"route":"#/stop/square-near-100"},"moment-square-near-100-beat2":{"id":"moment-square-near-100-beat2","kind":"moment","src":"story:square-near-100#beat2","badge":{"id":"story","label":"A story"},"title":"Meeting in the middle — on the notepad","body":"Mira: Then go down another 4. 96 − 4 = 92","cta":"Read the story","level":9,"route":"#/stop/square-near-100"},"moral-square-near-100-beat4":{"id":"moral-square-near-100-beat4","kind":"moral","src":"story:square-near-100#beat4","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Meeting in the middle”","body":"Ninety-two hundred and sixteen.","cta":"Read the story","level":9,"route":"#/stop/square-near-100"},"try-square-near-100-L9":{"id":"try-square-near-100-L9","kind":"try","level":9,"src":"try:square-near-100@9/1#0","title":"Squares near a hundred — your turn","route":"#/stop/square-near-100","cta":"Practise this stop","play":{"q":"96² = ?","opts":["9216","4","92"],"after":"Take the number down by its own gap from 100; then square the gap for the last two digits."}},"trick-square-endings-idea":{"id":"trick-square-endings-idea","kind":"trick","src":"stop:square-endings#idea","title":"How a square ends","body":"The last digit of a square depends only on the last digit of the number — and squares can only end in 0, 1, 4, 5, 6 or 9. When you multiply 47 by 47, the ones digit of the answer comes only from 7 × 7 = 49. The tens and hundreds never reach down into the ones column. So 47² ends in 9, just like 7² does.","cta":"Learn the trick","level":9,"route":"#/stop/square-endings"},"story-square-endings-open":{"id":"story-square-endings-open","kind":"story","src":"story:square-endings#open","badge":{"id":"story","label":"A story"},"title":"The locked door","body":"A puzzle door in the palace: \"The code is the last digit of 47 × 47.\" Dax reaches for a pencil. — with Theo and Dax.","art":"art/s-palace.webp","cta":"Read the story","level":9,"route":"#/stop/square-endings"},"hook-square-endings-hook":{"id":"hook-square-endings-hook","kind":"hook","src":"stop:square-endings#hook","title":"Can you? — How a square ends","body":"Could 5,847 be a square number? You can tell from one digit.","cta":"Find out how","level":9,"route":"#/stop/square-endings"},"idea-square-endings-case0":{"id":"idea-square-endings-case0","kind":"idea","src":"stop:square-endings#case0","title":"How a square ends: The last digit of a square","body":"Only the last digit of the number matters — the tens and hundreds never reach down into the ones column.","cta":"See it worked","level":9,"route":"#/stop/square-endings"},"worked-square-endings-worked0":{"id":"worked-square-endings-worked0","kind":"worked","src":"stop:square-endings#worked0","title":"Worked out — How a square ends: The last digit of a square","body":"The last digit of 47²: The last digit of 47 → 7 · 7 × 7 → 49 · Its last digit → 9","cta":"Watch it step by step","level":9,"route":"#/stop/square-endings"},"idea-square-endings-case1":{"id":"idea-square-endings-case1","kind":"idea","src":"stop:square-endings#case1","title":"How a square ends: Can a square end in…?","body":"Squares can only end in 0, 1, 4, 5, 6 or 9. A 2, 3, 7 or 8 at the end means “not a square”, however big the number.","cta":"See it worked","level":9,"route":"#/stop/square-endings"},"worked-square-endings-worked1":{"id":"worked-square-endings-worked1","kind":"worked","src":"stop:square-endings#worked1","title":"Worked out — How a square ends: Can a square end in…?","body":"Can a square number end in 7?: How many of the ten digits can end a square? (0, 1, 4, 5, 6, 9) → 6 · Is 7 one of them? → No","cta":"Watch it step by step","level":9,"route":"#/stop/square-endings"},"idea-square-endings-case2":{"id":"idea-square-endings-case2","kind":"idea","src":"stop:square-endings#case2","title":"How a square ends: Spot the square","body":"Cross out every number ending in 2, 3, 7 or 8 — they cannot be squares. The one left standing is.","cta":"See it worked","level":9,"route":"#/stop/square-endings"},"why-square-endings-why1":{"id":"why-square-endings-why1","kind":"why","src":"stop:square-endings#why1","title":"Why “How a square ends” works","body":"Now square the ten digits 0 to 9: 0, 1, 4, 9, 16, 25, 36, 49, 64, 81. Their last digits are 0, 1, 4, 9, 6, 5, 6, 9, 4, 1. Look which digits never turn up: 2, 3, 7 and 8. No square number ever ends in one of those — not one, however big.","cta":"See why","level":9,"route":"#/stop/square-endings"},"why-square-endings-why2":{"id":"why-square-endings-why2","kind":"why","src":"stop:square-endings#why2","title":"Why “How a square ends” works","body":"So 5,847 is not a square, instantly. Careful the other way round: ending in 1, 4, 5, 6, 9 or 0 only means it MIGHT be a square. 21 ends in 1 and is not one.","cta":"See why","level":9,"route":"#/stop/square-endings"},"algebra-square-endings-alg":{"id":"algebra-square-endings-alg","kind":"algebra","src":"stop:square-endings#alg","title":"The algebra behind “How a square ends”","body":"last digit of n² = last digit of (last digit of n)²","cta":"See why","level":9,"route":"#/stop/square-endings"},"moment-square-endings-beat4":{"id":"moment-square-endings-beat4","kind":"moment","src":"story:square-endings#beat4","badge":{"id":"story","label":"A story"},"title":"The locked door — on the notepad","body":"Theo: Never. I checked all ten digits. The code is 9 — and the full answer ends in it too. 47 × 47 = 2209","cta":"Read the story","level":9,"route":"#/stop/square-endings"},"moral-square-endings-beat5":{"id":"moral-square-endings-beat5","kind":"moral","src":"story:square-endings#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The locked door”","body":"Nine. The door clicks open. One digit was all we needed.","cta":"Read the story","level":9,"route":"#/stop/square-endings"},"try-square-endings-L9":{"id":"try-square-endings-L9","kind":"try","level":9,"src":"try:square-endings@9/2#0","title":"How a square ends — your turn","route":"#/stop/square-endings","cta":"Practise this stop","play":{"q":"Can a square number end in 6?","opts":["Yes","No"],"after":"The last digit of a square depends only on the last digit of the number — and squares can only end in 0, 1, 4, 5, 6 or 9."}},"trick-square-minus-idea":{"id":"trick-square-minus-idea","kind":"trick","src":"stop:square-minus#idea","title":"Squaring just below a ten","body":"Square the round number, take away two strips, and put back the little corner. 19² = (20 − 1)². Start with a 20-by-20 square: 400. To shrink it to 19 by 19, cut a strip 1 wide off the right side and another off the bottom. Each strip is 20 by 1 = 20.","cta":"Learn the trick","level":9,"route":"#/stop/square-minus"},"story-square-minus-open":{"id":"story-square-minus-open","kind":"story","src":"story:square-minus#open","badge":{"id":"story","label":"A story"},"title":"The banner that shrank","body":"A square palace banner must be 19 squares on each side. Ines has a 20-by-20 cloth. — with Kwame and Ines.","art":"art/s-palace.webp","cta":"Read the story","level":9,"route":"#/stop/square-minus"},"hook-square-minus-hook":{"id":"hook-square-minus-hook","kind":"hook","src":"stop:square-minus#hook","title":"Can you? — Squaring just below a ten","body":"19² — 19 is one short of 20.","cta":"Find out how","level":9,"route":"#/stop/square-minus"},"worked-square-minus-worked0":{"id":"worked-square-minus-worked0","kind":"worked","src":"stop:square-minus#worked0","title":"Worked out — Squaring just below a ten","body":"19²: The round square: 20² → 400 · Two strips: 2 × 20 × 1 → 40 · The corner: 1² → 1 · 400 − 40 + 1 → 361","cta":"Watch it step by step","level":9,"route":"#/stop/square-minus"},"why-square-minus-why1":{"id":"why-square-minus-why1","kind":"why","src":"stop:square-minus#why1","title":"Why “Squaring just below a ten” works","body":"But look at the corner where the two strips cross: that 1-by-1 square was in BOTH strips, so you took it away twice. Put it back once. 400 − 40 + 1 = 361.","cta":"See why","level":9,"route":"#/stop/square-minus"},"why-square-minus-why2":{"id":"why-square-minus-why2","kind":"why","src":"stop:square-minus#why2","title":"Why “Squaring just below a ten” works","body":"It is the (a + b)² picture run backwards. For any round number T and small gap d: (T − d)² = T² − 2 × T × d + d². 48² = 2500 − 200 + 4 = 2304.","cta":"See why","level":9,"route":"#/stop/square-minus"},"algebra-square-minus-alg":{"id":"algebra-square-minus-alg","kind":"algebra","src":"stop:square-minus#alg","title":"The algebra behind “Squaring just below a ten”","body":"(a − b)² = a² − 2ab + b²","cta":"See why","level":9,"route":"#/stop/square-minus"},"moment-square-minus-beat2":{"id":"moment-square-minus-beat2","kind":"moment","src":"story:square-minus#beat2","badge":{"id":"story","label":"A story"},"title":"The banner that shrank — on the notepad","body":"Kwame: Cut a strip one wide off the side, and one off the bottom. Twenty squares each. 2 × 20 = 40","cta":"Read the story","level":9,"route":"#/stop/square-minus"},"moral-square-minus-beat5":{"id":"moral-square-minus-beat5","kind":"moral","src":"story:square-minus#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The banner that shrank”","body":"Three hundred and sixty-one squares on the banner.","cta":"Read the story","level":9,"route":"#/stop/square-minus"},"try-square-minus-L9":{"id":"try-square-minus-L9","kind":"try","level":9,"src":"try:square-minus@9/1#0","title":"Squaring just below a ten — your turn","route":"#/stop/square-minus","cta":"Practise this stop","play":{"q":"39² = ?","opts":["1521","1600","80"],"after":"Square the round number, take away two strips, and put back the little corner."}},"trick-either-side-idea":{"id":"trick-either-side-idea","kind":"trick","src":"stop:either-side#idea","title":"Either side of a square","body":"Two numbers the same distance either side of a middle: square the middle, take away the distance squared. 23 × 17: the middle is 20, and each number is 3 away from it. 20² = 400 and 3² = 9, so 23 × 17 = 400 − 9 = 391.","cta":"Learn the trick","level":9,"route":"#/stop/either-side"},"story-either-side-open":{"id":"story-either-side-open","kind":"story","src":"story:either-side#open","badge":{"id":"story","label":"A story"},"title":"Seats in the stadium","body":"A stadium block has 23 rows of 17 seats. Nova is selling tickets and needs the total. — with Kwame and Nova.","art":"art/s-stadium.webp","cta":"Read the story","level":9,"route":"#/stop/either-side"},"hook-either-side-hook":{"id":"hook-either-side-hook","kind":"hook","src":"stop:either-side#hook","title":"Can you? — Either side of a square","body":"23 × 17 — both are 3 away from 20.","cta":"Find out how","level":9,"route":"#/stop/either-side"},"worked-either-side-worked0":{"id":"worked-either-side-worked0","kind":"worked","src":"stop:either-side#worked0","title":"Worked out — Either side of a square","body":"23 × 17: The middle number → 20 · How far each is from it → 3 · 20² → 400 · 3² → 9 · 400 − 9 → 391","cta":"Watch it step by step","level":9,"route":"#/stop/either-side"},"why-either-side-why1":{"id":"why-either-side-why1","kind":"why","src":"stop:either-side#why1","title":"Why “Either side of a square” works","body":"Picture the 23-by-17 rectangle. Cut a 3-wide strip off the long side and lay it along the short side. Now it is almost a 20-by-20 square — only a 3-by-3 corner is missing. So the rectangle is the square with the corner taken out.","cta":"See why","level":9,"route":"#/stop/either-side"},"why-either-side-why2":{"id":"why-either-side-why2","kind":"why","src":"stop:either-side#why2","title":"Why “Either side of a square” works","body":"That is why knowing your squares to 20 pays twice: 14 × 16 = 15² − 1 = 224, and 12 × 18 = 15² − 9 = 216. Any two numbers with a friendly middle become one square and one small square.","cta":"See why","level":9,"route":"#/stop/either-side"},"algebra-either-side-alg":{"id":"algebra-either-side-alg","kind":"algebra","src":"stop:either-side#alg","title":"The algebra behind “Either side of a square”","body":"(a + b)(a − b) = a² − b²","cta":"See why","level":9,"route":"#/stop/either-side"},"moment-either-side-beat3":{"id":"moment-either-side-beat3","kind":"moment","src":"story:either-side#beat3","badge":{"id":"story","label":"A story"},"title":"Seats in the stadium — on the notepad","body":"Nova: So it is nearly a 20-by-20 square… 20 × 20 = 400","cta":"Read the story","level":9,"route":"#/stop/either-side"},"moral-either-side-beat5":{"id":"moral-either-side-beat5","kind":"moral","src":"story:either-side#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Seats in the stadium”","body":"Three hundred and ninety-one seats. Middle squared, take the gap squared.","cta":"Read the story","level":9,"route":"#/stop/either-side"},"try-either-side-L9":{"id":"try-either-side-L9","kind":"try","level":9,"src":"try:either-side@9/1#0","title":"Either side of a square — your turn","route":"#/stop/either-side","cta":"Practise this stop","play":{"q":"16 × 18 = ?","opts":["288","17","1"],"after":"Two numbers the same distance either side of a middle: square the middle, take away the distance squared."}},"hook-ratio-share-hook":{"id":"hook-ratio-share-hook","kind":"hook","src":"stop:ratio-share#hook","title":"Can you? — Ratio: simplify and share","body":"Share 35 mangoes in the ratio 2 : 5. How many for each?","cta":"Find out how","level":9,"route":"#/stop/ratio-share"},"idea-ratio-share-case1":{"id":"idea-ratio-share-case1","kind":"idea","src":"stop:ratio-share#case1","title":"Ratio: simplify and share: Simplify a ratio","body":"Divide both sides by the same number, just like simplifying a fraction. The mix stays the same.","cta":"See it worked","level":9,"route":"#/stop/ratio-share"},"why-ratio-share-why2":{"id":"why-ratio-share-why2","kind":"why","src":"stop:ratio-share#why2","title":"Why “Ratio: simplify and share” works","body":"Simplifying a ratio is dividing both sides by the same number, just like a fraction: 12 : 18 is 2 : 3, because every 6 in the first matches every 6 in the second. The mix is the same; the numbers are smaller.","cta":"See why","level":9,"route":"#/stop/ratio-share"},"moral-ratio-share-beat5":{"id":"moral-ratio-share-beat5","kind":"moral","src":"story:ratio-share#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The mango crate”","body":"And 10 + 25 is all 35. Nothing left in the crate.","cta":"Read the story","level":9,"route":"#/stop/ratio-share"},"try-ratio-share-L9":{"id":"try-ratio-share-L9","kind":"try","level":9,"src":"try:ratio-share@9/2#0","title":"Ratio: simplify and share — your turn","route":"#/stop/ratio-share","cta":"Practise this stop","play":{"q":"Share 28 in the ratio 2 : 5. How much is the larger share?","opts":["20","7","4"],"after":"Add the parts to find how many equal shares there are. Find one share, then multiply."}},"hook-like-terms-hook":{"id":"hook-like-terms-hook","kind":"hook","src":"stop:like-terms#hook","title":"Can you? — Collecting like terms","body":"3x + 2y + 4x + y — can it be shorter?","cta":"Find out how","level":9,"route":"#/stop/like-terms"},"worked-like-terms-worked0":{"id":"worked-like-terms-worked0","kind":"worked","src":"stop:like-terms#worked0","title":"Worked out — Collecting like terms: One letter","body":"4m + m + 3m = □m. What goes in the box?: 4 + 1 → 5 · + 3 → 8","cta":"Watch it step by step","level":9,"route":"#/stop/like-terms"},"worked-like-terms-worked1":{"id":"worked-like-terms-worked1","kind":"worked","src":"stop:like-terms#worked1","title":"Worked out — Collecting like terms: Two letters","body":"Simplify: 3x + 2y + 4x + y: The x's: 3 + 4 → 7 · The y's: 2 + 1 → 3 · So the short form is → 7x + 3y","cta":"Watch it step by step","level":9,"route":"#/stop/like-terms"},"worked-like-terms-worked2":{"id":"worked-like-terms-worked2","kind":"worked","src":"stop:like-terms#worked2","title":"Worked out — Collecting like terms: Taking away x's","body":"5x + 3 − 8x + 2. The number in front of x?: The plain numbers: 3 + 2 → 5 · The x's: 5 − 8 → -3","cta":"Watch it step by step","level":9,"route":"#/stop/like-terms"},"why-like-terms-why2":{"id":"why-like-terms-why2","kind":"why","src":"stop:like-terms#why2","title":"Why “Collecting like terms” works","body":"Take-aways work the same way: 5x − 8x is 3 fewer lots than none, so −3x. The sign in front of a term belongs to it and travels with it.","cta":"See why","level":9,"route":"#/stop/like-terms"},"moment-like-terms-beat3":{"id":"moment-like-terms-beat3","kind":"moment","src":"story:like-terms#beat3","badge":{"id":"story","label":"A story"},"title":"The fruit basket — on the notepad","body":"Nova: And bananas with bananas. The lone y means one crate. 2 + 1 = 3","cta":"Read the story","level":9,"route":"#/stop/like-terms"},"try-like-terms-L9":{"id":"try-like-terms-L9","kind":"try","level":9,"src":"try:like-terms@9/2#0","title":"Collecting like terms — your turn","route":"#/stop/like-terms","cta":"Practise this stop","play":{"q":"Simplify: 2x + 8y + 8x + 4y","opts":["10x + 12y","10x + 12","11x + 12y"],"after":"Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart."}},"trick-nth-term-idea":{"id":"trick-nth-term-idea","kind":"trick","src":"stop:nth-term#idea","title":"The nth term","body":"Find the step. The nth term is the step × n, plus whatever fixes the first term. 5, 8, 11, 14 goes up by 3 each time. To reach the 20th term you start at the 1st and take 19 steps of 3: 5 + 19 × 3 = 62. Not 20 steps — the first term is already there before any step.","cta":"Learn the trick","level":9,"route":"#/stop/nth-term"},"story-nth-term-open":{"id":"story-nth-term-open","kind":"story","src":"story:nth-term#open","badge":{"id":"story","label":"A story"},"title":"Beach huts","body":"Beach hut 1 is 5 metres from the café, hut 2 is 8, hut 3 is 11, hut 4 is 14. How far is hut 20? — with Rafi and Theo.","art":"art/s-beach.webp","cta":"Read the story","level":9,"route":"#/stop/nth-term"},"idea-nth-term-case0":{"id":"idea-nth-term-case0","kind":"idea","src":"stop:nth-term#case0","title":"The nth term: Find a far term","body":"From the 1st term to the 20th is 19 steps, not 20 — the first term is there before any step.","cta":"See it worked","level":9,"route":"#/stop/nth-term"},"idea-nth-term-case1":{"id":"idea-nth-term-case1","kind":"idea","src":"stop:nth-term#case1","title":"The nth term: The nth-term rule","body":"The step is the times table. Compare the first term with the step: whatever you add (or take) to fix it is the number in the box.","cta":"See it worked","level":9,"route":"#/stop/nth-term"},"idea-nth-term-case2":{"id":"idea-nth-term-case2","kind":"idea","src":"stop:nth-term#case2","title":"The nth term: Which term is it?","body":"Run it backwards: how far from the first term, how many steps is that, then add one for the first term.","cta":"See it worked","level":9,"route":"#/stop/nth-term"},"why-nth-term-why1":{"id":"why-nth-term-why1","kind":"why","src":"stop:nth-term#why1","title":"Why “The nth term” works","body":"For a rule that works for every n, compare with the 3 times table: 3, 6, 9, 12. Our sequence is always 2 more, so the nth term is 3n + 2. Check: n = 1 gives 5. n = 20 gives 62.","cta":"See why","level":9,"route":"#/stop/nth-term"},"algebra-nth-term-alg":{"id":"algebra-nth-term-alg","kind":"algebra","src":"stop:nth-term#alg","title":"The algebra behind “The nth term”","body":"nth term = d·n + (a − d),  a = first term, d = step","cta":"See why","level":9,"route":"#/stop/nth-term"},"moral-nth-term-beat5":{"id":"moral-nth-term-beat5","kind":"moral","src":"story:nth-term#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “Beach huts”","body":"Sixty-two. And 3 × 20 + 2 agrees: the rule is 3n + 2.","cta":"Read the story","level":9,"route":"#/stop/nth-term"},"try-nth-term-L9":{"id":"try-nth-term-L9","kind":"try","level":9,"src":"try:nth-term@9/1#0","title":"The nth term — your turn","route":"#/stop/nth-term","cta":"Practise this stop","play":{"q":"8, 10, 12, 14, … What is the 10th term?","opts":["26","2","9"],"after":"Find the step. The nth term is the step × n, plus whatever fixes the first term."}},"trick-line-graph-idea":{"id":"trick-line-graph-idea","kind":"trick","src":"stop:line-graph#idea","title":"Straight-line graphs","body":"The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis. y = 2x + 1 is a machine: put in x, double it, add 1. x = 0 gives 1, x = 1 gives 3, x = 2 gives 5. Plot those points and they sit on one straight line.","cta":"Learn the trick","level":9,"route":"#/stop/line-graph"},"story-line-graph-open":{"id":"story-line-graph-open","kind":"story","src":"story:line-graph#open","badge":{"id":"story","label":"A story"},"title":"The tide post","body":"At the harbour, a tide post starts 1 metre deep and the water rises 2 metres every hour: y = 2x + 1. — with Mira and Dax.","art":"art/s-harbour.webp","cta":"Read the story","level":9,"route":"#/stop/line-graph"},"idea-line-graph-case0":{"id":"idea-line-graph-case0","kind":"idea","src":"stop:line-graph#case0","title":"Straight-line graphs: Find y from the rule","body":"Put x into the rule: times by m, then add c. Every point on the line obeys it.","cta":"See it worked","level":9,"route":"#/stop/line-graph"},"idea-line-graph-case1":{"id":"idea-line-graph-case1","kind":"idea","src":"stop:line-graph#case1","title":"Straight-line graphs: Gradient from two points","body":"The gradient is the climb divided by the steps across. Take the y's from each other, then the x's, then divide.","cta":"See it worked","level":9,"route":"#/stop/line-graph"},"why-line-graph-why1":{"id":"why-line-graph-why1","kind":"why","src":"stop:line-graph#why1","title":"Why “Straight-line graphs” works","body":"Why straight? Each step of 1 to the right always adds the same 2 to y — the same climb, every step, is exactly what \"straight\" means. That 2 is the gradient, m. The + 1 is where the line starts when x = 0: the crossing point, c.","cta":"See why","level":9,"route":"#/stop/line-graph"},"algebra-line-graph-alg":{"id":"algebra-line-graph-alg","kind":"algebra","src":"stop:line-graph#alg","title":"The algebra behind “Straight-line graphs”","body":"y = mx + c   ·   m = (y₂ − y₁) ÷ (x₂ − x₁)","cta":"See why","level":9,"route":"#/stop/line-graph"},"moral-line-graph-beat5":{"id":"moral-line-graph-beat5","kind":"moral","src":"story:line-graph#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The tide post”","body":"Seven metres deep after three hours.","cta":"Read the story","level":9,"route":"#/stop/line-graph"},"try-line-graph-L9":{"id":"try-line-graph-L9","kind":"try","level":9,"src":"try:line-graph@9/1#0","title":"Straight-line graphs — your turn","route":"#/stop/line-graph","cta":"Practise this stop","play":{"q":"y = x + 2. What is y when x = 7?","opts":["9","7","10"],"after":"The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis."}},"trick-percent-swap-idea":{"id":"trick-percent-swap-idea","kind":"trick","src":"stop:percent-swap#idea","title":"Percentages swap","body":"x% of y is always the same as y% of x. Swap them if the other way round is easier. 8% of 50 means 8 hundredths of 50: 8 × 50 ÷ 100. And 50% of 8 means 50 × 8 ÷ 100. Multiplication does not care about order, so they are the same number.","cta":"Learn the trick","level":9,"route":"#/stop/percent-swap"},"story-percent-swap-open":{"id":"story-percent-swap-open","kind":"story","src":"story:percent-swap#open","badge":{"id":"story","label":"A story"},"title":"The kite sale","body":"A sign in the shop: 8% off. The kite Dax wants costs 50 coins. — with Ines and Dax.","art":"art/s-shop.webp","cta":"Read the story","level":9,"route":"#/stop/percent-swap"},"hook-percent-swap-hook":{"id":"hook-percent-swap-hook","kind":"hook","src":"stop:percent-swap#hook","title":"Can you? — Percentages swap","body":"8% of 50 — sounds hard. It isn't.","cta":"Find out how","level":9,"route":"#/stop/percent-swap"},"idea-percent-swap-case0":{"id":"idea-percent-swap-case0","kind":"idea","src":"stop:percent-swap#case0","title":"Percentages swap: Swap to 50%","body":"50% is a half. Half of 8 is 4.","cta":"See it worked","level":9,"route":"#/stop/percent-swap"},"worked-percent-swap-worked0":{"id":"worked-percent-swap-worked0","kind":"worked","src":"stop:percent-swap#worked0","title":"Worked out — Percentages swap: Swap to 50%","body":"8% of 50: Swap it: 50% of 8 → 4","cta":"Watch it step by step","level":9,"route":"#/stop/percent-swap"},"idea-percent-swap-case1":{"id":"idea-percent-swap-case1","kind":"idea","src":"stop:percent-swap#case1","title":"Percentages swap: Swap to 10%","body":"10% is a tenth: divide by 10. A tenth of 30 is 3.","cta":"See it worked","level":9,"route":"#/stop/percent-swap"},"worked-percent-swap-worked1":{"id":"worked-percent-swap-worked1","kind":"worked","src":"stop:percent-swap#worked1","title":"Worked out — Percentages swap: Swap to 10%","body":"30% of 10: Swap it: 10% of 30 → 3","cta":"Watch it step by step","level":9,"route":"#/stop/percent-swap"},"idea-percent-swap-case2":{"id":"idea-percent-swap-case2","kind":"idea","src":"stop:percent-swap#case2","title":"Percentages swap: Swap to 25%","body":"25% is a quarter: halve, then halve again. 12, then 6, then 3.","cta":"See it worked","level":9,"route":"#/stop/percent-swap"},"worked-percent-swap-worked2":{"id":"worked-percent-swap-worked2","kind":"worked","src":"stop:percent-swap#worked2","title":"Worked out — Percentages swap: Swap to 25%","body":"12% of 25: Swap it: 25% of 12 → 3","cta":"Watch it step by step","level":9,"route":"#/stop/percent-swap"},"idea-percent-swap-case3":{"id":"idea-percent-swap-case3","kind":"idea","src":"stop:percent-swap#case3","title":"Percentages swap: Swap to 75%","body":"75% is three quarters. Find one quarter first — 16 ÷ 4 = 4 — then take three of them.","cta":"See it worked","level":9,"route":"#/stop/percent-swap"},"worked-percent-swap-worked3":{"id":"worked-percent-swap-worked3","kind":"worked","src":"stop:percent-swap#worked3","title":"Worked out — Percentages swap: Swap to 75%","body":"16% of 75: Swap it: 75% of 16 → 12","cta":"Watch it step by step","level":9,"route":"#/stop/percent-swap"},"idea-percent-swap-case4":{"id":"idea-percent-swap-case4","kind":"idea","src":"stop:percent-swap#case4","title":"Percentages swap: Swap to 20%, 40% or 60%","body":"20% is a fifth. For 40% find a fifth and double it: a fifth of 15 is 3, so two fifths is 6.","cta":"See it worked","level":9,"route":"#/stop/percent-swap"},"worked-percent-swap-worked4":{"id":"worked-percent-swap-worked4","kind":"worked","src":"stop:percent-swap#worked4","title":"Worked out — Percentages swap: Swap to 20%, 40% or 60%","body":"15% of 40: Swap it: 40% of 15 → 6","cta":"Watch it step by step","level":9,"route":"#/stop/percent-swap"},"why-percent-swap-why1":{"id":"why-percent-swap-why1","kind":"why","src":"stop:percent-swap#why1","title":"Why “Percentages swap” works","body":"50% of 8 is half of 8: 4. That is the answer to both.","cta":"See why","level":9,"route":"#/stop/percent-swap"},"why-percent-swap-why2":{"id":"why-percent-swap-why2","kind":"why","src":"stop:percent-swap#why2","title":"Why “Percentages swap” works","body":"The swap pays off when the new percentage is a friendly one. 50% is a half, 10% a tenth, 25% a quarter and 75% three quarters. 20% is a fifth, so 40% is two fifths and 60% three fifths.","cta":"See why","level":9,"route":"#/stop/percent-swap"},"algebra-percent-swap-alg":{"id":"algebra-percent-swap-alg","kind":"algebra","src":"stop:percent-swap#alg","title":"The algebra behind “Percentages swap”","body":"x% of y = xy ÷ 100 = y% of x","cta":"See why","level":9,"route":"#/stop/percent-swap"},"moment-percent-swap-beat3":{"id":"moment-percent-swap-beat3","kind":"moment","src":"story:percent-swap#beat3","badge":{"id":"story","label":"A story"},"title":"The kite sale — on the notepad","body":"Dax: Fifty percent is half. Half of 8… 50% of 8 = 4","cta":"Read the story","level":9,"route":"#/stop/percent-swap"},"moral-percent-swap-beat4":{"id":"moral-percent-swap-beat4","kind":"moral","src":"story:percent-swap#beat4","badge":{"id":"story","label":"A story"},"title":"Ines, in “The kite sale”","body":"So 4 coins off.","cta":"Read the story","level":9,"route":"#/stop/percent-swap"},"try-percent-swap-L9":{"id":"try-percent-swap-L9","kind":"try","level":9,"src":"try:percent-swap@9/1#0","title":"Percentages swap — your turn","route":"#/stop/percent-swap","cta":"Practise this stop","play":{"q":"40% of 10 = ?","opts":["4","5","3"],"after":"x% of y is always the same as y% of x. Swap them if the other way round is easier."}},"trick-square-up-idea":{"id":"trick-square-up-idea","kind":"trick","src":"stop:square-up#idea","title":"The next square up","body":"To get from n² to (n + 1)², add n and n + 1. 31² is 30² plus 30 plus 31 = 900 + 61 = 961.","cta":"Learn the trick","level":9,"route":"#/stop/square-up"},"story-square-up-open":{"id":"story-square-up-open","kind":"story","src":"story:square-up#open","badge":{"id":"story","label":"A story"},"title":"One size bigger","body":"Mira has laid a square of tiles 30 by 30. Now she wants it 31 by 31. — with Mira and Nova.","art":"art/s-room.webp","cta":"Read the story","level":9,"route":"#/stop/square-up"},"hook-square-up-hook":{"id":"hook-square-up-hook","kind":"hook","src":"stop:square-up#hook","title":"Can you? — The next square up","body":"You know 30² is 900. What is 31²?","cta":"Find out how","level":9,"route":"#/stop/square-up"},"worked-square-up-worked0":{"id":"worked-square-up-worked0","kind":"worked","src":"stop:square-up#worked0","title":"Worked out — The next square up","body":"31²: 30² → 900 · 30 + 31 → 61 · Add them → 961","cta":"Watch it step by step","level":9,"route":"#/stop/square-up"},"why-square-up-why1":{"id":"why-square-up-why1","kind":"why","src":"stop:square-up#why1","title":"Why “The next square up” works","body":"Picture a 30-by-30 square of tiles. To make it 31 by 31 you add a row of 30 along one side and a column of 31 along the other. Those are the two numbers you add.","cta":"See why","level":9,"route":"#/stop/square-up"},"algebra-square-up-alg":{"id":"algebra-square-up-alg","kind":"algebra","src":"stop:square-up#alg","title":"The algebra behind “The next square up”","body":"(n + 1)² = n² + n + (n + 1)","cta":"See why","level":9,"route":"#/stop/square-up"},"moment-square-up-beat2":{"id":"moment-square-up-beat2","kind":"moment","src":"story:square-up#beat2","badge":{"id":"story","label":"A story"},"title":"One size bigger — on the notepad","body":"Mira: No. Add a row of 30 along one side and a column of 31 along the other. 30 + 31 = 61","cta":"Read the story","level":9,"route":"#/stop/square-up"},"moral-square-up-beat4":{"id":"moral-square-up-beat4","kind":"moral","src":"story:square-up#beat4","badge":{"id":"story","label":"A story"},"title":"Mira, in “One size bigger”","body":"Nine hundred and sixty-one tiles.","cta":"Read the story","level":9,"route":"#/stop/square-up"},"try-square-up-L9":{"id":"try-square-up-L9","kind":"try","level":9,"src":"try:square-up@9/1#0","title":"The next square up — your turn","route":"#/stop/square-up","cta":"Practise this stop","play":{"q":"51² = ?","opts":["2601","2500","101"],"after":"To get from n² to (n + 1)², add n and n + 1."}},"trick-trig-sides-idea":{"id":"trick-trig-sides-idea","kind":"trick","src":"stop:trig-sides#idea","title":"Naming the sides","body":"The hypotenuse is always opposite the right angle; of the other two, the opposite side does not touch the marked angle and the adjacent side does. Every right-angled triangle has one side that never changes its name: the longest one, facing the right angle. It is the hypotenuse, wherever the triangle is turned.","cta":"Learn the trick","level":9,"route":"#/stop/trig-sides"},"story-trig-sides-open":{"id":"story-trig-sides-open","kind":"story","src":"story:trig-sides#open","badge":{"id":"story","label":"A story"},"title":"Whose side is it?","body":"On the beach, Mira draws a right-angled triangle in the sand with a stick: 3 m along, 4 m up, 5 m along the slope. — with Mira and Kwame.","art":"art/s-beach.webp","cta":"Read the story","level":9,"route":"#/stop/trig-sides"},"hook-trig-sides-hook":{"id":"hook-trig-sides-hook","kind":"hook","src":"stop:trig-sides#hook","title":"Can you? — Naming the sides","body":"The highlighted side: is it opposite the angle, next to it, or the hypotenuse? It depends which angle you are looking from.","cta":"Find out how","level":9,"route":"#/stop/trig-sides"},"idea-trig-sides-case0":{"id":"idea-trig-sides-case0","kind":"idea","src":"stop:trig-sides#case0","title":"Naming the sides: Hypotenuse","body":"Find the right angle first. The side facing it is the hypotenuse, whichever angle you look from.","cta":"See it worked","level":9,"route":"#/stop/trig-sides"},"idea-trig-sides-case1":{"id":"idea-trig-sides-case1","kind":"idea","src":"stop:trig-sides#case1","title":"Naming the sides: Opposite","body":"This side does not touch the marked angle at all — it is across the triangle from it.","cta":"See it worked","level":9,"route":"#/stop/trig-sides"},"idea-trig-sides-case2":{"id":"idea-trig-sides-case2","kind":"idea","src":"stop:trig-sides#case2","title":"Naming the sides: Adjacent","body":"The angle has moved to the top corner, so the same upright side now touches it: it is adjacent.","cta":"See it worked","level":9,"route":"#/stop/trig-sides"},"why-trig-sides-why1":{"id":"why-trig-sides-why1","kind":"why","src":"stop:trig-sides#why1","title":"Why “Naming the sides” works","body":"The other two names depend on which angle you stand at. Stand at the marked corner: one short side runs from your feet along to the right angle — it is next to you, so it is called adjacent (which means “lying next to”). The other short side is across the triangle from you, not touching your corner at all — it is opposite.","cta":"See why","level":9,"route":"#/stop/trig-sides"},"why-trig-sides-why2":{"id":"why-trig-sides-why2","kind":"why","src":"stop:trig-sides#why2","title":"Why “Naming the sides” works","body":"Move to the other sharp corner and the two short sides swap names: the side that was opposite now touches you, so it is adjacent. That is why you always find the angle first, then name the sides. The names are the start of trigonometry: sin, cos and tan are just the three ways of dividing one of these sides by another.","cta":"See why","level":9,"route":"#/stop/trig-sides"},"algebra-trig-sides-alg":{"id":"algebra-trig-sides-alg","kind":"algebra","src":"stop:trig-sides#alg","title":"The algebra behind “Naming the sides”","body":"hypotenuse: opposite the right angle · opposite: across from θ · adjacent: touches θ (and is not the hypotenuse)","cta":"See why","level":9,"route":"#/stop/trig-sides"},"moral-trig-sides-beat6":{"id":"moral-trig-sides-beat6","kind":"moral","src":"story:trig-sides#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “Whose side is it?”","body":"Only the hypotenuse keeps its name. Find the angle first, then name the sides.","cta":"Read the story","level":9,"route":"#/stop/trig-sides"},"trick-tan-height-idea":{"id":"trick-tan-height-idea","kind":"trick","src":"stop:tan-height#idea","title":"Tan: how tall is the tower?","body":"tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle. Draw the triangle: the boat, the foot of the tower, the lamp. The tower is opposite the 35° angle and the flat sea is adjacent to it. Now draw a smaller triangle with the same 35° angle — say 10 m along and however high it has to be. It is the same shape, just shrunk, so its height ÷ length is the same number as the big one’s.","cta":"Learn the trick","level":9,"route":"#/stop/tan-height"},"story-tan-height-open":{"id":"story-tan-height-open","kind":"story","src":"story:tan-height#open","badge":{"id":"story","label":"A story"},"title":"Measuring the tower","body":"Theo wants the height of the lighthouse. He paces 40 m from its foot along the harbour wall, and Vesper measures the angle up to the lamp: 35°. — with Theo and Vesper.","art":"art/s-harbour.webp","cta":"Read the story","level":9,"route":"#/stop/tan-height"},"idea-tan-height-case0":{"id":"idea-tan-height-case0","kind":"idea","src":"stop:tan-height#case0","title":"Tan: how tall is the tower?: Find the height","body":"The height is opposite and the distance adjacent, so height = distance × tan of the angle.","cta":"See it worked","level":9,"route":"#/stop/tan-height"},"idea-tan-height-case1":{"id":"idea-tan-height-case1","kind":"idea","src":"stop:tan-height#case1","title":"Tan: how tall is the tower?: Find the distance","body":"Going the other way, undo the times: distance = height ÷ tan of the angle.","cta":"See it worked","level":9,"route":"#/stop/tan-height"},"why-tan-height-why1":{"id":"why-tan-height-why1","kind":"why","src":"stop:tan-height#why1","title":"Why “Tan: how tall is the tower?” works","body":"That number belongs to the angle, not to any one triangle. For 35° it is about 0.7: every right-angled triangle with a 35° angle is about 0.7 times as tall as it is long. The number is called the tangent of 35°, written tan 35°. Calculators know it; here you are given it.","cta":"See why","level":9,"route":"#/stop/tan-height"},"algebra-tan-height-alg":{"id":"algebra-tan-height-alg","kind":"algebra","src":"stop:tan-height#alg","title":"The algebra behind “Tan: how tall is the tower?”","body":"tan θ = opposite ÷ adjacent ⇒ opposite = adjacent × tan θ","cta":"See why","level":9,"route":"#/stop/tan-height"},"moral-tan-height-beat6":{"id":"moral-tan-height-beat6","kind":"moral","src":"story:tan-height#beat6","badge":{"id":"story","label":"A story"},"title":"Vesper, in “Measuring the tower”","body":"And the lamp-room plaque says 28 m.","cta":"Read the story","level":9,"route":"#/stop/tan-height"},"try-tan-height-L9":{"id":"try-tan-height-L9","kind":"try","level":9,"src":"try:tan-height@9/1#0","title":"Tan: how tall is the tower? — your turn","route":"#/stop/tan-height","cta":"Practise this stop","play":{"q":"A boat is 30 m from the foot of the lighthouse. The angle up to the top is 17°. Using tan 17° ≈ 0.3, how tall is the lighthouse, in metres?","opts":["9","10","8"],"after":"tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle."}},"trick-sin-cos-side-idea":{"id":"trick-sin-cos-side-idea","kind":"trick","src":"stop:sin-cos-side#idea","title":"Sin and cos: the ladder","body":"With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos. The ladder is the hypotenuse. Just as with tan, every right-angled triangle with a 53° angle is the same shape, so the height ÷ ladder is the same number for all of them. That number is the sine of 53°, sin 53° — about 0.8. The foot’s distance ÷ ladder is the cosine, cos 53° — about 0.6.","cta":"Learn the trick","level":9,"route":"#/stop/sin-cos-side"},"story-sin-cos-side-open":{"id":"story-sin-cos-side-open","kind":"story","src":"story:sin-cos-side#open","badge":{"id":"story","label":"A story"},"title":"The painter’s ladder","body":"A painter leans a 10 m ladder on a tall wall at 53° to the ground. Ines wants to know how high it reaches. — with Ines and Mira.","art":"art/s-city.webp","cta":"Read the story","level":9,"route":"#/stop/sin-cos-side"},"idea-sin-cos-side-case0":{"id":"idea-sin-cos-side-case0","kind":"idea","src":"stop:sin-cos-side#case0","title":"Sin and cos: the ladder: Height up the wall: sin","body":"The height is opposite the angle at the ground, and the ladder is the hypotenuse: height = ladder × sin.","cta":"See it worked","level":9,"route":"#/stop/sin-cos-side"},"idea-sin-cos-side-case1":{"id":"idea-sin-cos-side-case1","kind":"idea","src":"stop:sin-cos-side#case1","title":"Sin and cos: the ladder: Foot from the wall: cos","body":"The ground side touches the angle — it is adjacent — so use cos: distance = ladder × cos.","cta":"See it worked","level":9,"route":"#/stop/sin-cos-side"},"idea-sin-cos-side-case2":{"id":"idea-sin-cos-side-case2","kind":"idea","src":"stop:sin-cos-side#case2","title":"Sin and cos: the ladder: Ladder from height","body":"Now the ladder is the unknown. Height = ladder × sin, so undo it: ladder = height ÷ sin.","cta":"See it worked","level":9,"route":"#/stop/sin-cos-side"},"idea-sin-cos-side-case3":{"id":"idea-sin-cos-side-case3","kind":"idea","src":"stop:sin-cos-side#case3","title":"Sin and cos: the ladder: Ladder from foot","body":"The same undoing with the ground side: ladder = distance along the ground ÷ cos.","cta":"See it worked","level":9,"route":"#/stop/sin-cos-side"},"why-sin-cos-side-why1":{"id":"why-sin-cos-side-why1","kind":"why","src":"stop:sin-cos-side#why1","title":"Why “Sin and cos: the ladder” works","body":"So height = 10 × 0.8 = 8 m, and the foot is 10 × 0.6 = 6 m out. Check with Pythagoras: 6² + 8² = 36 + 64 = 100 = 10². The three ratios all come from the same triangle, so they must agree.","cta":"See why","level":9,"route":"#/stop/sin-cos-side"},"algebra-sin-cos-side-alg":{"id":"algebra-sin-cos-side-alg","kind":"algebra","src":"stop:sin-cos-side#alg","title":"The algebra behind “Sin and cos: the ladder”","body":"sin θ = opp ÷ hyp · cos θ = adj ÷ hyp ⇒ opp = hyp × sin θ , adj = hyp × cos θ","cta":"See why","level":9,"route":"#/stop/sin-cos-side"},"moral-sin-cos-side-beat6":{"id":"moral-sin-cos-side-beat6","kind":"moral","src":"story:sin-cos-side#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “The painter’s ladder”","body":"It reaches 8 metres up.","cta":"Read the story","level":9,"route":"#/stop/sin-cos-side"},"try-sin-cos-side-L9":{"id":"try-sin-cos-side-L9","kind":"try","level":9,"src":"try:sin-cos-side@9/1#0","title":"Sin and cos: the ladder — your turn","route":"#/stop/sin-cos-side","cta":"Practise this stop","play":{"q":"A 20 m ladder leans on the lighthouse wall, at 60° to the ground. sin 60° ≈ 0.87 and cos 60° = 0.5. How far is its foot from the wall, in metres?","opts":["10","11","9"],"after":"With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos."}},"trick-special-angles-idea":{"id":"trick-special-angles-idea","kind":"trick","src":"stop:special-angles#idea","title":"The three special angles","body":"Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°). Cut a square of side 1 along its diagonal. Each half is a right-angled triangle with two sides of 1 and two angles of 45°. Its hypotenuse is √2, by Pythagoras (1² + 1² = 2). So tan 45° = 1 ÷ 1 = 1, and sin 45° = cos 45° = 1 ÷ √2.","cta":"Learn the trick","level":9,"route":"#/stop/special-angles"},"story-special-angles-open":{"id":"story-special-angles-open","kind":"story","src":"story:special-angles#open","badge":{"id":"story","label":"A story"},"title":"The folded napkin","body":"After supper, Vesper folds a square napkin corner to corner. Each half is a right-angled triangle with two equal short sides. — with Vesper and Mira.","art":"art/s-night.webp","cta":"Read the story","level":9,"route":"#/stop/special-angles"},"idea-special-angles-case0":{"id":"idea-special-angles-case0","kind":"idea","src":"stop:special-angles#case0","title":"The three special angles: Sin: opposite ÷ hypotenuse","body":"In the half-equilateral, the short side 1 over the hypotenuse 2 is a half — and 1 is opposite the 30° corner.","cta":"See it worked","level":9,"route":"#/stop/special-angles"},"idea-special-angles-case1":{"id":"idea-special-angles-case1","kind":"idea","src":"stop:special-angles#case1","title":"The three special angles: Cos: adjacent ÷ hypotenuse","body":"The same 1 over 2 — but for cos the side must TOUCH the angle, and it touches the 60° corner.","cta":"See it worked","level":9,"route":"#/stop/special-angles"},"idea-special-angles-case2":{"id":"idea-special-angles-case2","kind":"idea","src":"stop:special-angles#case2","title":"The three special angles: Tan: opposite ÷ adjacent","body":"Tan is 1 when the two short sides are equal — and that only happens in the half-square, at 45°.","cta":"See it worked","level":9,"route":"#/stop/special-angles"},"why-special-angles-why1":{"id":"why-special-angles-why1","kind":"why","src":"stop:special-angles#why1","title":"Why “The three special angles” works","body":"Now take an equilateral triangle of side 2 — all three angles are 60° — and cut it down the middle. Each half has a hypotenuse of 2, a bottom of 1, and a height of √3 (because 1² + 3 = 4 = 2²). The angles are 60° at the bottom, 30° at the top (half of 60°), and the right angle.","cta":"See why","level":9,"route":"#/stop/special-angles"},"algebra-special-angles-alg":{"id":"algebra-special-angles-alg","kind":"algebra","src":"stop:special-angles#alg","title":"The algebra behind “The three special angles”","body":"sin 30° = cos 60° = 1/2 · sin 45° = cos 45° = 1/√2 · tan 45° = 1 · sin 60° = cos 30° = √3/2 · tan 60° = √3 · tan 30° = 1/√3","cta":"See why","level":9,"route":"#/stop/special-angles"},"moral-special-angles-beat5":{"id":"moral-special-angles-beat5","kind":"moral","src":"story:special-angles#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “The folded napkin”","body":"So sin 30° is exactly one half. No calculator — just a folded napkin.","cta":"Read the story","level":9,"route":"#/stop/special-angles"},"try-special-angles-L9":{"id":"try-special-angles-L9","kind":"try","level":9,"src":"try:special-angles@9/1#0","title":"The three special angles — your turn","route":"#/stop/special-angles","cta":"Practise this stop","play":{"q":"cos x = 1/2, and x is between 0° and 90°. What is x?","opts":["60°","30°","45°"],"after":"Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°)."}},"trick-bearings-idea":{"id":"trick-bearings-idea","kind":"trick","src":"stop:bearings#idea","title":"Bearings: the way back","body":"A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°. A bearing says which way to go by one number: stand facing north, turn clockwise, and say how many degrees you turned. East is 090°, south is 180°, west is 270°. Bearings are always written with three figures — 065°, not 65° — so a number shouted across a windy deck cannot be misheard as a different one.","cta":"Learn the trick","level":9,"route":"#/stop/bearings"},"story-bearings-open":{"id":"story-bearings-open","kind":"story","src":"story:bearings#open","badge":{"id":"story","label":"A story"},"title":"The way home","body":"Night on the water. Kwame steers the keeper’s boat out from the lighthouse on a bearing of 065° to check a buoy. — with Kwame and Theo.","art":"art/s-night.webp","cta":"Read the story","level":9,"route":"#/stop/bearings"},"idea-bearings-case0":{"id":"idea-bearings-case0","kind":"idea","src":"stop:bearings#case0","title":"Bearings: the way back: Out under 180°: add","body":"Half a turn more still fits inside a whole turn, so add 180°.","cta":"See it worked","level":9,"route":"#/stop/bearings"},"idea-bearings-case1":{"id":"idea-bearings-case1","kind":"idea","src":"stop:bearings#case1","title":"Bearings: the way back: Out over 180°: take away","body":"Adding 180° would go past 360°, all the way round. Take 180° away instead to face the opposite way.","cta":"See it worked","level":9,"route":"#/stop/bearings"},"why-bearings-why1":{"id":"why-bearings-why1","kind":"why","src":"stop:bearings#why1","title":"Why “Bearings: the way back” works","body":"The way back is exactly the opposite direction: half a turn, 180°, from the way out. From 065°, turn another 180° and you face 245°. If the way out is already more than 180°, adding would go past a whole turn, so take 180 away instead: the way back from 300° is 120°.","cta":"See why","level":9,"route":"#/stop/bearings"},"algebra-bearings-alg":{"id":"algebra-bearings-alg","kind":"algebra","src":"stop:bearings#alg","title":"The algebra behind “Bearings: the way back”","body":"back bearing = bearing + 180° (if under 180°) , bearing − 180° (if over 180°)","cta":"See why","level":9,"route":"#/stop/bearings"},"moral-bearings-beat5":{"id":"moral-bearings-beat5","kind":"moral","src":"story:bearings#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The way home”","body":"Bearing 245. The lamp should be dead ahead.","cta":"Read the story","level":9,"route":"#/stop/bearings"},"try-bearings-L9":{"id":"try-bearings-L9","kind":"try","level":9,"src":"try:bearings@9/1#0","title":"Bearings: the way back — your turn","route":"#/stop/bearings","cta":"Practise this stop","play":{"q":"A ship leaves the lighthouse on a bearing of 060°. What bearing takes it straight back? Type the number of degrees (a leading zero is fine either way).","opts":["240","241","239"],"after":"A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°."}},"trick-scatter-correlation-idea":{"id":"trick-scatter-correlation-idea","kind":"trick","src":"stop:scatter-correlation#idea","title":"Scatter graphs and correlation","body":"If the dots drift up to the right the correlation is positive; down to the right, negative; a shapeless cloud, none. A scatter graph puts one reading along the bottom and another up the side, and each night becomes one dot. If nights with a big x tend to have a big y, the cloud of dots leans up to the right: positive correlation. If a big x tends to come with a small y, it leans down: negative correlation. If knowing x tells you nothing about y, the dots make a round, shapeless cloud: no correlation.","cta":"Learn the trick","level":9,"route":"#/stop/scatter-correlation"},"story-scatter-correlation-open":{"id":"story-scatter-correlation-open","kind":"story","src":"story:scatter-correlation#open","badge":{"id":"story","label":"A story"},"title":"The keeper’s log","body":"The keeper logs, for 12 summer days, the hours of sunshine and the number of people on the beach. Theo plots a dot for each day. — with Theo and Ines.","art":"art/s-beach.webp","cta":"Read the story","level":9,"route":"#/stop/scatter-correlation"},"hook-scatter-correlation-hook":{"id":"hook-scatter-correlation-hook","kind":"hook","src":"stop:scatter-correlation#hook","title":"Can you? — Scatter graphs and correlation","body":"Twelve nights of the keeper’s log, plotted as dots. Do the two readings rise together, fall together, or have nothing to do with each other?","cta":"Find out how","level":9,"route":"#/stop/scatter-correlation"},"idea-scatter-correlation-case0":{"id":"idea-scatter-correlation-case0","kind":"idea","src":"stop:scatter-correlation#case0","title":"Scatter graphs and correlation: Positive","body":"The dots lean up to the right: the bigger one reading, the bigger the other tends to be.","cta":"See it worked","level":9,"route":"#/stop/scatter-correlation"},"idea-scatter-correlation-case1":{"id":"idea-scatter-correlation-case1","kind":"idea","src":"stop:scatter-correlation#case1","title":"Scatter graphs and correlation: Negative","body":"The dots lean down to the right: as one reading grows, the other tends to shrink.","cta":"See it worked","level":9,"route":"#/stop/scatter-correlation"},"idea-scatter-correlation-case2":{"id":"idea-scatter-correlation-case2","kind":"idea","src":"stop:scatter-correlation#case2","title":"Scatter graphs and correlation: None","body":"A round, shapeless cloud with no lean either way. Knowing one reading tells you nothing about the other.","cta":"See it worked","level":9,"route":"#/stop/scatter-correlation"},"why-scatter-correlation-why1":{"id":"why-scatter-correlation-why1","kind":"why","src":"stop:scatter-correlation#why1","title":"Why “Scatter graphs and correlation” works","body":"The closer the dots crowd round a straight line, the stronger the correlation. Statisticians measure it with a number called r, between −1 and 1: near 1 is strong positive, near −1 strong negative, near 0 none. Every graph on this stop was checked: the strong ones have r beyond ±0.7 and the “none” ones have r between −0.2 and 0.2.","cta":"See why","level":9,"route":"#/stop/scatter-correlation"},"why-scatter-correlation-why2":{"id":"why-scatter-correlation-why2","kind":"why","src":"stop:scatter-correlation#why2","title":"Why “Scatter graphs and correlation” works","body":"Correlation is not cause. Ice-cream sales and sunburn rise together, but ice cream does not burn anyone — hot sunny days cause both. A scatter graph shows that two things move together; it can never, on its own, show that one makes the other happen.","cta":"See why","level":9,"route":"#/stop/scatter-correlation"},"algebra-scatter-correlation-alg":{"id":"algebra-scatter-correlation-alg","kind":"algebra","src":"stop:scatter-correlation#alg","title":"The algebra behind “Scatter graphs and correlation”","body":"up to the right: positive · down to the right: negative · no lean: none (−1 ≤ r ≤ 1)","cta":"See why","level":9,"route":"#/stop/scatter-correlation"},"moral-scatter-correlation-beat5":{"id":"moral-scatter-correlation-beat5","kind":"moral","src":"story:scatter-correlation#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The keeper’s log”","body":"So a scatter graph shows things moving together — never, by itself, which one causes which.","cta":"Read the story","level":9,"route":"#/stop/scatter-correlation"},"trick-best-fit-estimate-idea":{"id":"trick-best-fit-estimate-idea","kind":"trick","src":"stop:best-fit-estimate#idea","title":"The line of best fit","body":"Find how much y changes for each 1 across, then walk along the line from a point you know. When a scatter graph has a strong correlation, a single straight line drawn through the middle of the dots — with about as many dots above it as below — sums up the trend. It is called the line of best fit, and you can use it to estimate a y for an x you never measured.","cta":"Learn the trick","level":9,"route":"#/stop/best-fit-estimate"},"story-best-fit-estimate-open":{"id":"story-best-fit-estimate-open","kind":"story","src":"story:best-fit-estimate#open","badge":{"id":"story","label":"A story"},"title":"Reading the line","body":"Kwame has plotted the harbour log and drawn a line of best fit. It passes through (4, 6) and (12, 10). What does it say at x = 8? — with Kwame and Ines.","art":"art/s-harbour.webp","cta":"Read the story","level":9,"route":"#/stop/best-fit-estimate"},"hook-best-fit-estimate-hook":{"id":"hook-best-fit-estimate-hook","kind":"hook","src":"stop:best-fit-estimate#hook","title":"Can you? — The line of best fit","body":"The line of best fit goes through (4, 6) and (12, 10). What does it say y is when x = 8?","cta":"Find out how","level":9,"route":"#/stop/best-fit-estimate"},"idea-best-fit-estimate-case0":{"id":"idea-best-fit-estimate-case0","kind":"idea","src":"stop:best-fit-estimate#case0","title":"The line of best fit: Inside the data","body":"Work out how much y climbs for each 1 across, then walk along from a point you know.","cta":"See it worked","level":9,"route":"#/stop/best-fit-estimate"},"worked-best-fit-estimate-worked0":{"id":"worked-best-fit-estimate-worked0","kind":"worked","src":"stop:best-fit-estimate#worked0","title":"Worked out — The line of best fit: Inside the data","body":"A line of best fit passes through (4, 6) and (12, 10). Use the line to estimate y when x = 8.: From x = 4 to x = 12, how much does y change? (use − if it falls) → 4 · So for each 1 across, y changes by 4 ÷ 8 → 0.5 · x = 8 is 4 across from x = 4: 6 + (4) × (0.5) → 8","cta":"Watch it step by step","level":9,"route":"#/stop/best-fit-estimate"},"idea-best-fit-estimate-case1":{"id":"idea-best-fit-estimate-case1","kind":"idea","src":"stop:best-fit-estimate#case1","title":"The line of best fit: A falling line","body":"When the line goes down, y changes by a negative amount for each step across — so walking right makes y smaller.","cta":"See it worked","level":9,"route":"#/stop/best-fit-estimate"},"idea-best-fit-estimate-case2":{"id":"idea-best-fit-estimate-case2","kind":"idea","src":"stop:best-fit-estimate#case2","title":"The line of best fit: Beyond the data","body":"The sum is the same, but nobody measured out here. That is extrapolation: the trend may bend or stop, so trust it less.","cta":"See it worked","level":9,"route":"#/stop/best-fit-estimate"},"why-best-fit-estimate-why1":{"id":"why-best-fit-estimate-why1","kind":"why","src":"stop:best-fit-estimate#why1","title":"Why “The line of best fit” works","body":"A straight line climbs by the same amount for every step across. From (4, 6) to (12, 10), x goes 8 across and y goes up 4, so y goes up 4 ÷ 8 = 0.5 for each 1 across. At x = 8 you are 4 across from x = 4, so y = 6 + 4 × 0.5 = 8.","cta":"See why","level":9,"route":"#/stop/best-fit-estimate"},"why-best-fit-estimate-why2":{"id":"why-best-fit-estimate-why2","kind":"why","src":"stop:best-fit-estimate#why2","title":"Why “The line of best fit” works","body":"Estimating inside the data (interpolation) is fairly safe: the dots are right there around the line. Estimating outside the data (extrapolation) is risky: nobody measured there, and the trend may bend or stop. The arithmetic is the same, but trust the answer less — the line is a summary of the dots, not a law of nature.","cta":"See why","level":9,"route":"#/stop/best-fit-estimate"},"algebra-best-fit-estimate-alg":{"id":"algebra-best-fit-estimate-alg","kind":"algebra","src":"stop:best-fit-estimate#alg","title":"The algebra behind “The line of best fit”","body":"gradient m = (y₂ − y₁) ÷ (x₂ − x₁) ; y = y₁ + (x − x₁) × m","cta":"See why","level":9,"route":"#/stop/best-fit-estimate"},"moment-best-fit-estimate-beat2":{"id":"moment-best-fit-estimate-beat2","kind":"moment","src":"story:best-fit-estimate#beat2","badge":{"id":"story","label":"A story"},"title":"Reading the line — on the notepad","body":"Ines: Four up for eight across — a half for every one across. 4 ÷ 8 = 0.5","cta":"Read the story","level":9,"route":"#/stop/best-fit-estimate"},"moral-best-fit-estimate-beat5":{"id":"moral-best-fit-estimate-beat5","kind":"moral","src":"story:best-fit-estimate#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Reading the line”","body":"Inside the data, so it is a fair guess. Out at x = 30, where nobody measured, I would not trust it.","cta":"Read the story","level":9,"route":"#/stop/best-fit-estimate"},"try-best-fit-estimate-L9":{"id":"try-best-fit-estimate-L9","kind":"try","level":9,"src":"try:best-fit-estimate@9/1#0","title":"The line of best fit — your turn","route":"#/stop/best-fit-estimate","cta":"Practise this stop","play":{"q":"A line of best fit passes through (0, 4) and (8, 20). Use the line to estimate y when x = 4.","opts":["12","16","2"],"after":"Find how much y changes for each 1 across, then walk along the line from a point you know."}},"trick-tree-diagram-idea":{"id":"trick-tree-diagram-idea","kind":"trick","src":"stop:tree-diagram#idea","title":"Tree diagrams","body":"Multiply along the branches for one path; add the paths when more than one path counts. A tree diagram draws every way two chancy things can turn out. The first event splits into branches, each labelled with its chance, and every branch splits again for the second event. Each path from the root to a tip is one complete story — late then on time, say — and the paths cover everything that can happen.","cta":"Learn the trick","level":9,"route":"#/stop/tree-diagram"},"story-tree-diagram-open":{"id":"story-tree-diagram-open","kind":"story","src":"story:tree-diagram#open","badge":{"id":"story","label":"A story"},"title":"Two ferries","body":"The morning ferry is late on 1 day in 4. The evening ferry is late on 2 days in 5, whatever the morning one did. How often are both late? — with Ines and Vesper.","art":"art/s-harbour.webp","cta":"Read the story","level":9,"route":"#/stop/tree-diagram"},"idea-tree-diagram-case0":{"id":"idea-tree-diagram-case0","kind":"idea","src":"stop:tree-diagram#case0","title":"Tree diagrams: One path: multiply","body":"Follow the one path where both happen, and multiply the chances along it — a fraction of a fraction.","cta":"See it worked","level":9,"route":"#/stop/tree-diagram"},"idea-tree-diagram-case1":{"id":"idea-tree-diagram-case1","kind":"idea","src":"stop:tree-diagram#case1","title":"Tree diagrams: A \"not\" branch","body":"The other branch is whatever is left of 1: late 1/4 means on time 3/4. Find it first, then multiply along.","cta":"See it worked","level":9,"route":"#/stop/tree-diagram"},"idea-tree-diagram-case2":{"id":"idea-tree-diagram-case2","kind":"idea","src":"stop:tree-diagram#case2","title":"Tree diagrams: Two paths: add","body":"Exactly one late can happen two ways. Multiply along each path, then add the two, because either will do.","cta":"See it worked","level":9,"route":"#/stop/tree-diagram"},"why-tree-diagram-why1":{"id":"why-tree-diagram-why1","kind":"why","src":"stop:tree-diagram#why1","title":"Why “Tree diagrams” works","body":"Why multiply? Think of 100 days. The morning ferry is late on 1/4 of them: 25 days. On 2/5 of those 25, the evening ferry is late as well: 10 days. So both are late on 10 days in 100 — 1/10 — and 1/4 × 2/5 = 2/20 = 1/10. Taking a fraction of a fraction is multiplying. (This works when the second chance is the same whatever the first did; here it is.)","cta":"See why","level":9,"route":"#/stop/tree-diagram"},"algebra-tree-diagram-alg":{"id":"algebra-tree-diagram-alg","kind":"algebra","src":"stop:tree-diagram#alg","title":"The algebra behind “Tree diagrams”","body":"P(A and B) = P(A) × P(B) (independent) · P(one path or another) = sum of the paths","cta":"See why","level":9,"route":"#/stop/tree-diagram"},"moral-tree-diagram-beat5":{"id":"moral-tree-diagram-beat5","kind":"moral","src":"story:tree-diagram#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Two ferries”","body":"One quarter times two fifths: two twentieths, which is one tenth.","cta":"Read the story","level":9,"route":"#/stop/tree-diagram"},"try-tree-diagram-L9":{"id":"try-tree-diagram-L9","kind":"try","level":9,"src":"try:tree-diagram@9/1#0","title":"Tree diagrams — your turn","route":"#/stop/tree-diagram","cta":"Practise this stop","play":{"q":"The chance that the first net comes up full is 1/3. The chance that the second net comes up full is 3/4, whatever the first one does. What is the chance that the first net comes up full and the second net comes up full?","opts":["1/4","1/3","3/4"],"after":"Multiply along the branches for one path; add the paths when more than one path counts."}},"trick-expected-frequency-idea":{"id":"trick-expected-frequency-idea","kind":"trick","src":"stop:expected-frequency#idea","title":"Expected frequency","body":"Expected number = probability × number of trials: take that fraction of the trials. A probability is a long-run share. A chance of rain of 3/10 means that, over many, many nights, about 3 in every 10 are wet. So in 60 nights you expect 3/10 of 60: split the 60 nights into tens — 6 of them — with 3 wet nights in each, 18 altogether. That is all expected frequency is: the probability × the number of trials.","cta":"Learn the trick","level":9,"route":"#/stop/expected-frequency"},"story-expected-frequency-open":{"id":"story-expected-frequency-open","kind":"story","src":"story:expected-frequency#open","badge":{"id":"story","label":"A story"},"title":"Sixty nights of weather","body":"The keeper’s logbook shows rain on about 3 nights in every 10. Theo is planning the next 60 nights and wants to know how many will be wet. — with Ines and Theo.","art":"art/s-night.webp","cta":"Read the story","level":9,"route":"#/stop/expected-frequency"},"idea-expected-frequency-case0":{"id":"idea-expected-frequency-case0","kind":"idea","src":"stop:expected-frequency#case0","title":"Expected frequency: A fraction chance","body":"Split the trials into equal groups — the bottom of the fraction — and take the top number of those groups.","cta":"See it worked","level":9,"route":"#/stop/expected-frequency"},"idea-expected-frequency-case1":{"id":"idea-expected-frequency-case1","kind":"idea","src":"stop:expected-frequency#case1","title":"Expected frequency: Faces of a die","body":"The chance is not written down: count the faces that win, out of 6, and simplify before you share.","cta":"See it worked","level":9,"route":"#/stop/expected-frequency"},"idea-expected-frequency-case2":{"id":"idea-expected-frequency-case2","kind":"idea","src":"stop:expected-frequency#case2","title":"Expected frequency: A decimal chance","body":"A decimal is a fraction in disguise: 0.15 is 15 hundredths, which is 3/20.","cta":"See it worked","level":9,"route":"#/stop/expected-frequency"},"idea-expected-frequency-case3":{"id":"idea-expected-frequency-case3","kind":"idea","src":"stop:expected-frequency#case3","title":"Expected frequency: Two things at once","body":"Multiply along the tree-diagram path first to get one chance, then take that share of the trials.","cta":"See it worked","level":9,"route":"#/stop/expected-frequency"},"why-expected-frequency-why2":{"id":"why-expected-frequency-why2","kind":"why","src":"stop:expected-frequency#why2","title":"Why “Expected frequency” works","body":"It works however the chance is written. On a die, count the faces that win first: “a 5 or a 6” is 2 faces out of 6, so the chance is 2/6 = 1/3. A decimal is a fraction too: 0.15 is 15 hundredths, or 3/20, so in 200 nights expect 200 ÷ 20 × 3 = 30. And for two things at once, multiply along the tree-diagram path first, then take that share of the trials: ferries late 1/4 and 2/5 of the time make both late 1/10 of the time — about 20 days in 200.","cta":"See why","level":9,"route":"#/stop/expected-frequency"},"moment-expected-frequency-beat3":{"id":"moment-expected-frequency-beat3","kind":"moment","src":"story:expected-frequency#beat3","badge":{"id":"story","label":"A story"},"title":"Sixty nights of weather — on the notepad","body":"Theo: Six lots of ten nights, with 3 wet ones in each. 6 × 3 = 18","cta":"Read the story","level":9,"route":"#/stop/expected-frequency"},"try-expected-frequency-L9":{"id":"try-expected-frequency-L9","kind":"try","level":9,"src":"try:expected-frequency@9/1#0","title":"Expected frequency — your turn","route":"#/stop/expected-frequency","cta":"Practise this stop","play":{"q":"A fair die is rolled 60 times. How many times would you expect to roll a 5 or a 6?","opts":["20","1/3","21"],"after":"Expected number = probability × number of trials: take that fraction of the trials."}},"trick-inequalities-idea":{"id":"trick-inequalities-idea","kind":"trick","src":"stop:inequalities#idea","title":"Inequalities","body":"Solve it like an equation, doing the same to both sides — but if you multiply or divide by a negative, turn the sign round. An inequality is a balance that is tipped: 3x + 4 < 19 says the left pan is lighter. Take 4 off both pans and it is still lighter: 3x < 15. Share both pans into 3 and each third is still lighter: x < 5. So any number below 5 works — 4, 3, 0, −10, even 4.9 — and the biggest whole number that works is 4. Not 5: 3 × 5 + 4 is exactly 19, and 19 is not less than 19.","cta":"Learn the trick","level":9,"route":"#/stop/inequalities"},"story-inequalities-open":{"id":"story-inequalities-open","kind":"story","src":"story:inequalities#open","badge":{"id":"story","label":"A story"},"title":"The weight limit","body":"The lighthouse crane can lift less than 19 tonnes. The cradle weighs 4 tonnes and each crate weighs 3 tonnes. How many crates can go up at once? — with Kwame and Theo.","art":"art/s-harbour.webp","cta":"Read the story","level":9,"route":"#/stop/inequalities"},"idea-inequalities-case0":{"id":"idea-inequalities-case0","kind":"idea","src":"stop:inequalities#case0","title":"Inequalities: Less than: the largest","body":"Solve it like an equation. x < 5 lets in 4 but not 5 itself, so the largest whole number is one below.","cta":"See it worked","level":9,"route":"#/stop/inequalities"},"idea-inequalities-case1":{"id":"idea-inequalities-case1","kind":"idea","src":"stop:inequalities#case1","title":"Inequalities: More than: the smallest","body":"Now the answers run upwards, so look for the smallest. x > 4 does not include 4, so start one above.","cta":"See it worked","level":9,"route":"#/stop/inequalities"},"idea-inequalities-case2":{"id":"idea-inequalities-case2","kind":"idea","src":"stop:inequalities#case2","title":"Inequalities: Or equal to","body":"≤ and ≥ include the edge itself, so the boundary number is allowed this time.","cta":"See it worked","level":9,"route":"#/stop/inequalities"},"idea-inequalities-case3":{"id":"idea-inequalities-case3","kind":"idea","src":"stop:inequalities#case3","title":"Inequalities: The whole answer","body":"The answer is a whole range, written like x ≥ 3. Dividing by a positive number, the sign stays the one you started with.","cta":"See it worked","level":9,"route":"#/stop/inequalities"},"idea-inequalities-case4":{"id":"idea-inequalities-case4","kind":"idea","src":"stop:inequalities#case4","title":"Inequalities: Dividing by a negative","body":"Dividing both sides by a negative number mirrors the number line, so the sign turns round: < becomes >.","cta":"See it worked","level":9,"route":"#/stop/inequalities"},"why-inequalities-why1":{"id":"why-inequalities-why1","kind":"why","src":"stop:inequalities#why1","title":"Why “Inequalities” works","body":"< means “less than” and ≤ means “less than or equal to”. So 3x + 4 ≤ 19 gives x ≤ 5, and now 5 itself is allowed.","cta":"See why","level":9,"route":"#/stop/inequalities"},"algebra-inequalities-alg":{"id":"algebra-inequalities-alg","kind":"algebra","src":"stop:inequalities#alg","title":"The algebra behind “Inequalities”","body":"a·x + b < c ⇒ x < (c − b) ÷ a if a > 0 ; x > (c − b) ÷ a if a < 0","cta":"See why","level":9,"route":"#/stop/inequalities"},"moral-inequalities-beat6":{"id":"moral-inequalities-beat6","kind":"moral","src":"story:inequalities#beat6","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The weight limit”","body":"The biggest whole number below 5.","cta":"Read the story","level":9,"route":"#/stop/inequalities"},"word-coefficient":{"id":"word-coefficient","kind":"word","src":"dictionary:coefficient#def","title":"coefficient","body":"The number in front of a letter, which multiplies it. For example: In 4x it is 4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":9},"wordq-coefficient":{"id":"wordq-coefficient","kind":"wordq","src":"dictionary:coefficient#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 4x it is 4.”","opts":["coefficient","hundredth","long multiplication"],"after":"coefficient: The number in front of a letter, which multiplies it."},"level":9},"word-identity":{"id":"word-identity","kind":"word","src":"dictionary:identity#def","title":"identity","body":"A statement with an = sign that is true for every value of its letters. For example: (a + b)² = a² + 2ab + b², whatever a and b are.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":9},"wordq-identity":{"id":"wordq-identity","kind":"wordq","src":"dictionary:identity#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “(a + b)² = a² + 2ab + b², whatever a and b are.”","opts":["identity","hypotenuse","Euler’s formula"],"after":"identity: A statement with an = sign that is true for every value of its letters."},"level":9},"word-like-terms":{"id":"word-like-terms","kind":"word","src":"dictionary:like terms#def","title":"like terms","body":"Parts of an expression with exactly the same letters, which can be added together. For example: 3a + 5a = 8a, but 3a + 5b stays as it is.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":9},"wordq-like-terms":{"id":"wordq-like-terms","kind":"wordq","src":"dictionary:like terms#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3a + 5a = 8a, but 3a + 5b stays as it is.”","opts":["like terms","square root","Roman numerals"],"after":"like terms: Parts of an expression with exactly the same letters, which can be added together."},"level":9},"formula-square-of-sum":{"id":"formula-square-of-sum","kind":"formula","src":"formula:square-of-sum","title":"Squaring a sum","body":"(a + b)² = a² + 2ab + b². A square of side a + b is a², b² and two a × b strips.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Squaring a sum: 34², as (30 + 4)².","opts":["1156","1157","1155"],"after":"30² = 900, 2 × 30 × 4 = 240, 4² = 16 · 900 + 240 + 16 = 1156"},"level":9},"formula-why-square-of-sum-0":{"id":"formula-why-square-of-sum-0","kind":"formula-why","src":"formula:square-of-sum#why0","title":"Why (a + b)² = a² + 2ab + b²","body":"Draw a square with sides a + b and cut each side where a ends. The big square splits into four pieces: an a by a square, a b by b square, and two a by b rectangles.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-why-square-of-sum-1":{"id":"formula-why-square-of-sum-1","kind":"formula-why","src":"formula:square-of-sum#why1","title":"Why (a + b)² = a² + 2ab + b²","body":"Add the pieces and you have a² + ab + ab + b², which is a² + 2ab + b². That is why 23² = 20² + 2 × 20 × 3 + 3² = 400 + 120 + 9 = 529.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-story-square-of-sum":{"id":"formula-story-square-of-sum","kind":"formula-story","src":"formula:square-of-sum#story","badge":{"id":"story","label":"A story"},"title":"The herb garden grows","body":"Mira’s square herb garden is 20 by 20 tiles. She makes it 3 tiles bigger each way. How many tiles now? — with Mira and Nova.","art":"art/s-garden.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-try-square-of-sum":{"id":"formula-try-square-of-sum","kind":"formula-try","src":"formula:square-of-sum#gen0","title":"Squaring a sum — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Use (a + b)²: 33² = (30 + 3)² = ?","opts":["1089","1090","1088"],"after":"(a + b)² = a² + 2ab + b²"},"level":9},"formula-square-of-difference":{"id":"formula-square-of-difference","kind":"formula","src":"formula:square-of-difference","title":"Squaring a difference","body":"(a − b)² = a² − 2ab + b². Take off two strips — and put back the corner you took twice.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Squaring a difference: 49², as (50 − 1)².","opts":["2401","2402","2400"],"after":"50² = 2500, 2 × 50 × 1 = 100, 1² = 1 · 2500 − 100 + 1 = 2401"},"level":9},"formula-why-square-of-difference-0":{"id":"formula-why-square-of-difference-0","kind":"formula-why","src":"formula:square-of-difference#why0","title":"Why (a − b)² = a² − 2ab + b²","body":"Start with an a by a square. Cut a strip b wide off one side and another off the top. Each strip is a by b, so you take away 2ab.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-why-square-of-difference-1":{"id":"formula-why-square-of-difference-1","kind":"formula-why","src":"formula:square-of-difference#why1","title":"Why (a − b)² = a² − 2ab + b²","body":"But the little b by b corner was in both strips, so it was taken away twice. Put it back once: (a − b)² = a² − 2ab + b². That is why 49² = 2500 − 100 + 1 = 2401.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-story-square-of-difference":{"id":"formula-story-square-of-difference","kind":"formula-story","src":"formula:square-of-difference#story","badge":{"id":"story","label":"A story"},"title":"Fewer chairs","body":"The hall’s chairs stand in a square, 30 rows of 30. For the concert Kwame takes away one row and one column. How many are left? — with Kwame and Pip.","art":"art/s-hall.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-try-square-of-difference":{"id":"formula-try-square-of-difference","kind":"formula-try","src":"formula:square-of-difference#gen0","title":"Squaring a difference — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Use (a − b)²: 68² = (70 − 2)² = ?","opts":["4624","4625","4623"],"after":"(a − b)² = a² − 2ab + b²"},"level":9},"formula-why-nth-term-0":{"id":"formula-why-nth-term-0","kind":"formula-why","src":"formula:nth-term#why0","title":"Why Tₙ = a + (n − 1) × d","body":"In a sequence that goes up by the same step d each time, the first number is a. To reach the 2nd you take 1 step; to reach the 3rd you take 2 steps; to reach the nth you take n − 1 steps.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-story-nth-term":{"id":"formula-story-nth-term","kind":"formula-story","src":"formula:nth-term#story","badge":{"id":"story","label":"A story"},"title":"The cup pyramid","body":"At the fair Dax lines up rows of cups: 4 in the first row, 7 in the second, 10 in the third. How many would row 25 need? — with Dax and Kwame.","art":"art/s-fair.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-pythagoras":{"id":"formula-pythagoras","kind":"formula","src":"formula:pythagoras","title":"Pythagoras’ theorem","body":"a² + b² = c². The squares on the two short sides, 9 + 16, fill the square on the longest side, 25.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Pythagoras’ theorem: Shorter sides 6 cm and 8 cm. The longest side?","opts":["10","11","9"],"after":"6² + 8² = 36 + 64 = 100 · c = √100 = 10 cm"},"level":9},"formula-try-pythagoras":{"id":"formula-try-pythagoras","kind":"formula-try","src":"formula:pythagoras#gen0","title":"Pythagoras’ theorem — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A right-angled triangle has a longest side of 5 cm and one shorter side of 4 cm. The other shorter side (in cm)?","opts":["3","4","2"],"after":"a² + b² = c²"},"level":9},"formula-simple-interest":{"id":"formula-simple-interest","kind":"formula","src":"formula:simple-interest","title":"Simple interest","body":"I = P × r × t ÷ 100. The same block of interest is added every year.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Simple interest: £200 at 5% a year for 3 years.","opts":["30","31","29"],"after":"one year: 5% of 200 = 10 · I = 10 × 3 = £30"},"level":9},"formula-why-simple-interest-0":{"id":"formula-why-simple-interest-0","kind":"formula-why","src":"formula:simple-interest#why0","title":"Why I = P × r × t ÷ 100","body":"Simple interest adds the same amount every year: r% of the starting money P. One year’s interest is P × r ÷ 100.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-why-simple-interest-1":{"id":"formula-why-simple-interest-1","kind":"formula-why","src":"formula:simple-interest#why1","title":"Why I = P × r × t ÷ 100","body":"After t years you have had t equal helpings, so I = P × r × t ÷ 100. (Many savings accounts use compound interest instead, where each year’s interest earns interest too, so they grow a little faster.)","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-story-simple-interest":{"id":"formula-story-simple-interest","kind":"formula-story","src":"formula:simple-interest#story","badge":{"id":"story","label":"A story"},"title":"The savings account","body":"Nova’s aunt puts £300 in a savings account for her. It pays 4% simple interest a year. How much interest after 5 years? — with Ines and Nova.","art":"art/s-city.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-try-simple-interest":{"id":"formula-try-simple-interest","kind":"formula-try","src":"formula:simple-interest#gen0","title":"Simple interest — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Simple interest on £300 at 6% a year for 4 years (in £)?","opts":["72","73","71"],"after":"I = P × r × t ÷ 100"},"level":9},"formula-ratio-share":{"id":"formula-ratio-share","kind":"formula","src":"formula:ratio-share","title":"Sharing in a ratio","body":"a : b of x → x ÷ (a + b) × a. 2 : 3 means 5 equal parts; one share takes 2, the other 3.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Sharing in a ratio: £40 shared in the ratio 3 : 5. The first share?","opts":["15","16","14"],"after":"3 + 5 = 8 parts; 40 ÷ 8 = 5 · 3 × 5 = £15 (and 5 × 5 = £25)"},"level":9},"formula-why-ratio-share-0":{"id":"formula-why-ratio-share-0","kind":"formula-why","src":"formula:ratio-share#why0","title":"Why a : b of x → x ÷ (a + b) × a","body":"A ratio of 2 : 3 means that for every 2 in one share there are 3 in the other — 5 equal parts in every group.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-why-ratio-share-1":{"id":"formula-why-ratio-share-1","kind":"formula-why","src":"formula:ratio-share#why1","title":"Why a : b of x → x ÷ (a + b) × a","body":"So cut the whole amount into a + b equal parts. One part is x ÷ (a + b); one share gets a of them and the other gets b. Check: the two shares must add back to x.","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-story-ratio-share":{"id":"formula-story-ratio-share","kind":"formula-story","src":"formula:ratio-share#story","badge":{"id":"story","label":"A story"},"title":"Mixing green paint","body":"Suki is mixing green paint: blue and yellow in the ratio 2 : 3. She needs 20 litres of green. — with Rafi and Suki.","art":"art/s-room.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":9},"formula-try-ratio-share":{"id":"formula-try-ratio-share","kind":"formula-try","src":"formula:ratio-share#gen0","title":"Sharing in a ratio — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"£32 is shared in the ratio 3 : 5. How much is the first share (in £)?","opts":["12","13","11"],"after":"a : b of x → x ÷ (a + b) × a"},"level":9},"stone-vedic-yavadunam":{"src":"journey:vedic/yavadunam#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-yavadunam","kind":"stone","title":"However much it falls short — Yāvadūnam","body":"To square a number near a base, go down by its gap once more — then square the gap for the end.","level":9},"stone-vedic-yavadunam-1":{"src":"journey:vedic/yavadunam#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-yavadunam-1","kind":"stone-step","title":"However much it falls short (2 of 3)","body":"96²: 96 is 4 short of 100. Go down another 4: 92. Square the gap: 16. Answer 9216. Above works going up: 103² → 106 and 09, so 10609.","level":9},"stone-vedic-yavadunam-2":{"src":"journey:vedic/yavadunam#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-yavadunam-2","kind":"stone-step","title":"However much it falls short (3 of 3)","body":"Why: (B − d)² = B(B − 2d) + d². It is the Nikhilam cross with both numbers the same. Near 100 the d² takes two places; near 10, one place (and any extra carries).","level":9},"stone-try-vedic-yavadunam":{"src":"journey:vedic/yavadunam#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-yavadunam","kind":"stone-try","title":"However much it falls short — try it","play":{"q":"103² = ?","opts":["10609","3","106"],"after":"Squares near a base"},"level":9}};
